export default function () {
  this.route("boards");
  this.route("boardsBoard", { path: "/boards/:slug/:id" });
  this.route("boardsBoardConfigure", {
    path: "/boards/:slug/:id/configure",
  });
  this.route("boardsBoardCard", {
    path: "/boards/:slug/:id/cards/:card_id",
  });
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { generateLinkifyFunction } from "discourse/lib/text";

let cachedLinkify = null;

export default class AutoLinkedText extends Component {
  @tracked linkify = cachedLinkify;

  constructor() {
    super(...arguments);
    if (!this.linkify) {
      generateLinkifyFunction({}).then((instance) => {
        cachedLinkify = instance;
        if (!this.isDestroying) {
          this.linkify = instance;
        }
      });
    }
  }

  get segments() {
    const text = this.args.text ?? "";
    if (!this.linkify || !text) {
      return [{ isUrl: false, value: text }];
    }

    const matches = this.linkify.match(text);
    if (!matches) {
      return [{ isUrl: false, value: text }];
    }

    const result = [];
    let lastIndex = 0;

    for (const match of matches) {
      if (match.index > lastIndex) {
        result.push({
          isUrl: false,
          value: text.slice(lastIndex, match.index),
        });
      }
      result.push({ isUrl: true, value: match.raw, href: match.url });
      lastIndex = match.index + match.raw.length;
    }

    if (lastIndex < text.length) {
      result.push({ isUrl: false, value: text.slice(lastIndex) });
    }

    return result;
  }

  <template>
    {{#each this.segments as |segment|}}
      {{#if segment.isUrl}}
        <a
          href={{segment.href}}
          rel="noopener noreferrer"
          target="_blank"
        >{{segment.value}}</a>
      {{else}}
        {{segment.value}}
      {{/if}}
    {{/each}}
  </template>
}
import Component from "@glimmer/component";
import DAccessControlField from "discourse/ui-kit/d-access-control-field";
import { i18n } from "discourse-i18n";
import { boardPermissionOptions } from "../lib/boards-access-control.js";

export default class BoardsAccessControlField extends Component {
  get aclTarget() {
    return {
      type: "Boards::Board",
      key: "Boards::Board",
      id: this.args.boardId,
      name: i18n("boards.manage.board"),
    };
  }

  <template>
    <DAccessControlField
      @aclTarget={{this.aclTarget}}
      @canManageOwners={{@canManageOwners}}
      @description={{@description}}
      @form={{@form}}
      @isNew={{@isNew}}
      @name={{@name}}
      @onAccessLossConfirmed={{@onAccessLossConfirmed}}
      @onChange={{@onChange}}
      @onSet={{@onSet}}
      @showOptional={{@showOptional}}
      @title={{@title}}
      @transformPermissionOptions={{boardPermissionOptions}}
      @validation={{@validation}}
    />
  </template>
}
import Category from "discourse/models/category";
import Site from "discourse/models/site";

export function loadCategory(id) {
  return Category.findById(id) || Category.asyncFindById(id);
}

export function loadCategories(ids = []) {
  ids = [...new Set(ids.filter(Boolean))];
  const categories = Category.findByIds(ids);

  if (
    !Site.current().lazy_load_categories ||
    categories.length === ids.length
  ) {
    return categories;
  }

  return Category.asyncFindByIds(ids);
}

export async function preloadCategories(ids) {
  try {
    await loadCategories(ids);
  } catch {}
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { fn } from "@ember/helper";
import { action } from "@ember/object";
import { includes } from "discourse/truth-helpers";
import DAsyncContent from "discourse/ui-kit/d-async-content";
import DButton from "discourse/ui-kit/d-button";
import DModal from "discourse/ui-kit/d-modal";
import { i18n } from "discourse-i18n";
import { loadCategories } from "../../lib/boards-categories.js";

export default class BoardsConstraintFix extends Component {
  @tracked selectedCategoryId = null;
  @tracked selectedTagNames = [];

  get canSave() {
    const { mismatches } = this.args.model;
    if (mismatches.needsCategory && !this.selectedCategoryId) {
      return false;
    }
    if (mismatches.needsTags && this.selectedTagNames.length === 0) {
      return false;
    }
    return true;
  }

  @action
  async loadCategoryOptions(ids) {
    const categories = await loadCategories(ids);
    if (!this.isDestroying && ids.length === 1) {
      this.selectedCategoryId = categories[0]?.id ?? null;
    }

    return categories;
  }

  @action
  selectCategory(categoryId) {
    this.selectedCategoryId = categoryId;
  }

  @action
  toggleTag(tagName) {
    if (this.selectedTagNames.includes(tagName)) {
      this.selectedTagNames = this.selectedTagNames.filter(
        (t) => t !== tagName
      );
    } else {
      this.selectedTagNames = [...this.selectedTagNames, tagName];
    }
  }

  @action
  confirm() {
    if (!this.canSave) {
      return;
    }

    const result = {};
    const { mismatches } = this.args.model;

    if (mismatches.needsCategory) {
      result.category_id = this.selectedCategoryId;
    }
    if (mismatches.needsTags) {
      result.tag_names = this.selectedTagNames;
    }

    this.args.model.onConfirm(result);
    this.args.closeModal();
  }

  @action
  cancel() {
    this.args.model.onCancel?.();
    this.args.closeModal();
  }

  <template>
    <DModal
      class="discourse-boards-constraint-fix-modal"
      @closeModal={{this.cancel}}
      @title={{i18n "boards.board.constraint_fix_title"}}
    >
      <:body>
        <p class="discourse-boards-constraint-fix__description">
          {{i18n "boards.board.constraint_fix_description"}}
        </p>

        {{#if @model.mismatches.needsCategory}}
          <div class="discourse-boards-constraint-fix__field">
            <label>{{i18n "boards.board.constraint_fix_category"}}</label>
            <div class="discourse-boards-constraint-fix__options">
              <DAsyncContent
                @asyncData={{this.loadCategoryOptions}}
                @context={{@model.mismatches.boardCategoryIds}}
              >
                <:content as |categories|>
                  {{#each categories as |cat|}}
                    <DButton
                      class={{if
                        (eq this.selectedCategoryId cat.id)
                        "btn-primary discourse-boards-constraint-fix__option--selected"
                        "btn-default"
                      }}
                      data-category-id={{cat.id}}
                      @action={{fn this.selectCategory cat.id}}
                      @translatedLabel={{cat.name}}
                    />
                  {{/each}}
                </:content>
              </DAsyncContent>
            </div>
          </div>
        {{/if}}

        {{#if @model.mismatches.needsTags}}
          <div class="discourse-boards-constraint-fix__field">
            <label>{{i18n "boards.board.constraint_fix_tags"}}</label>
            <div class="discourse-boards-constraint-fix__options">
              {{#each @model.mismatches.boardTagNames as |tagName|}}
                <DButton
                  class={{if
                    (includes this.selectedTagNames tagName)
                    "btn-primary discourse-boards-constraint-fix__option--selected"
                    "btn-default"
                  }}
                  data-tag-name={{tagName}}
                  @action={{fn this.toggleTag tagName}}
                  @translatedLabel={{tagName}}
                />
              {{/each}}
            </div>
          </div>
        {{/if}}
      </:body>
      <:footer>
        <DButton
          class="btn-primary"
          @action={{this.confirm}}
          @disabled={{not this.canSave}}
          @label="boards.board.constraint_fix_confirm"
        />
        <DButton class="btn-flat" @action={{this.cancel}} @label="cancel" />
      </:footer>
    </DModal>
  </template>
}
import Component from "@glimmer/component";
import { fn } from "@ember/helper";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { trustHTML } from "@ember/template";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import { isValidHex, normalizeHex } from "discourse/lib/color-transformations";
import DButton from "discourse/ui-kit/d-button";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import { i18n } from "discourse-i18n";
import BoardsConstraintFix from "./modal/boards-constraint-fix.gjs";

export default class BoardsAddFromTopicColumnSubmenu extends Component {
  @service messageBus;
  @service modal;
  @service toasts;

  get availableColumns() {
    return this.args.data.board.columns.filter(
      (column) => !column.topic_is_member
    );
  }

  get alreadyAddedColumns() {
    return this.args.data.board.columns.filter(
      (column) => column.topic_is_member
    );
  }

  @action
  async addToColumn(column) {
    const response = await this.#checkConstraints(column);

    if (!response) {
      return;
    }

    if (response.constraints_need_fixing) {
      return this.#onConstraintMismatch(column, response);
    }

    await this.#completeAddToColumn(column);
  }

  @action
  async removeFromColumn(column) {
    try {
      await ajax(
        `/boards/api/boards/${this.args.data.board.id}/cards/${column.topic_card_id}`,
        {
          type: "DELETE",
        }
      );

      this.toasts.success({
        duration: "short",
        data: {
          message: i18n("boards.board.removed_topic_from_board", {
            boardName: this.args.data.board.unicode_name,
            columnName: column.unicode_title,
          }),
        },
      });

      this.args.close({ data: { cardSaved: true } });
    } catch (error) {
      popupAjaxError(error);
    }
  }

  columnStyle(column) {
    if (!isValidHex(column.color)) {
      return null;
    }

    return trustHTML(
      `--discourse-boards-column-icon-color: #${normalizeHex(column.color)};`
    );
  }

  async #checkConstraints(column) {
    try {
      const response = await ajax(
        `/boards/api/boards/${this.args.data.board.id}/check-constraint-mismatches`,
        {
          method: "PUT",
          data: {
            topic_id: this.args.data.topic.id,
            target_column_id: column.id,
          },
        }
      );
      return response;
    } catch (error) {
      popupAjaxError(error);
      return null;
    }
  }

  #onConstraintMismatch(column, response) {
    const mismatches = {
      needsTags: response.tags_needed.length > 0,
      needsCategory: response.categories_needed.length > 0,
      boardTagNames: response.tags_needed,
      boardCategoryIds: response.categories_needed,
    };

    this.modal.show(BoardsConstraintFix, {
      model: {
        topic: this.args.data.topic,
        board: this.args.data.board,
        column,
        mismatches,
        onConfirm: (result) => this.#completeAddToColumn(column, result),
      },
    });
  }

  async #completeAddToColumn(column, constraintFixResult = null) {
    const data = {
      client_id: this.messageBus.clientId,
      card: {
        column_id: column.id,
        topic_id: this.args.data.topic.id,
      },
    };

    if (constraintFixResult) {
      data.constraint_fix = constraintFixResult;
    }

    try {
      await ajax(`/boards/api/boards/${this.args.data.board.id}/cards`, {
        type: "POST",
        data,
      });

      this.toasts.success({
        duration: "short",
        data: {
          message: i18n("boards.board.added_topic_to_board", {
            boardName: this.args.data.board.unicode_name,
            columnName: column.unicode_title,
          }),
        },
      });

      this.args.close({ data: { cardSaved: true } });
    } catch (error) {
      popupAjaxError(error);
      return;
    }
  }

  <template>
    <DDropdownMenu
      class="discourse-boards-add-from-topic-column-menu"
      as |dropdown|
    >
      {{#if this.availableColumns.length}}
        <dropdown.subheader>
          {{@data.board.unicode_name}}
        </dropdown.subheader>
        {{#each this.availableColumns as |column|}}
          <dropdown.item>
            <DButton
              class="btn-transparent discourse-boards-add-from-topic-column-menu__column"
              style={{this.columnStyle column}}
              @action={{fn this.addToColumn column}}
              @icon={{column.icon}}
              @translatedLabel={{column.fancyTitle}}
            />
          </dropdown.item>
        {{/each}}
      {{/if}}
      {{#if this.alreadyAddedColumns.length}}
        <dropdown.subheader>
          {{i18n "boards.topic_footer.already_added"}}
        </dropdown.subheader>
        {{#each this.alreadyAddedColumns as |column|}}
          <dropdown.item>
            <DButton
              class="btn-transparent discourse-boards-add-from-topic-column-menu__column"
              style={{this.columnStyle column}}
              @action={{fn this.removeFromColumn column}}
              @icon={{column.icon}}
              @suffixIcon="xmark"
              @translatedLabel={{column.fancyTitle}}
            />
          </dropdown.item>
        {{/each}}
      {{/if}}
    </DDropdownMenu>
  </template>
}
import { tracked } from "@glimmer/tracking";

export default class Card {
  static create(args = {}) {
    if (args instanceof Card) {
      return args;
    }
    return new Card(args);
  }

  @tracked assigned_to;
  @tracked board_id;
  @tracked card_type;
  @tracked column_id;
  @tracked created_at;
  @tracked column_changed_at;
  @tracked created_by;
  @tracked id;
  @tracked inline_onebox_data;
  @tracked notes;
  @tracked position;
  @tracked recency_at;
  @tracked tag_ids;
  @tracked tags;
  @tracked title;
  @tracked topic;
  @tracked topic_id;
  @tracked unicode_title;
  @tracked updated_at;

  constructor(args = {}) {
    Object.assign(this, args);
  }

  get fancyTitle() {
    const titleSource =
      this.card_type === "topic" && this.topic ? this.topic : this;
    return titleSource.unicode_title || titleSource.title;
  }

  copy(overrides = {}) {
    return new Card({
      assigned_to: this.assigned_to,
      board_id: this.board_id,
      card_type: this.card_type,
      column_changed_at: this.column_changed_at,
      column_id: this.column_id,
      created_at: this.created_at,
      created_by: this.created_by,
      id: this.id,
      inline_onebox_data: this.inline_onebox_data,
      notes: this.notes,
      position: this.position,
      recency_at: this.recency_at,
      tag_ids: this.tag_ids,
      tags: this.tags,
      title: this.title,
      topic: this.topic,
      topic_id: this.topic_id,
      unicode_title: this.unicode_title,
      updated_at: this.updated_at,
      ...overrides,
    });
  }
}
import { tracked } from "@glimmer/tracking";
import Card from "./card.js";

export default class Column {
  static create(args = {}) {
    if (args instanceof Column) {
      return args;
    }
    return new Column(args);
  }

  @tracked cards;
  @tracked color;
  @tracked default_sort;
  @tracked icon;
  @tracked id;
  @tracked move_to_assigned;
  @tracked move_to_category_id;
  @tracked move_to_status;
  @tracked position;
  @tracked tag_id;
  @tracked tag_name;
  @tracked title;
  @tracked unicode_title;

  constructor(args = {}) {
    Object.assign(this, args);
    this.cards = (args.cards || []).map((card) => Card.create(card));
  }

  get fancyTitle() {
    return this.unicode_title || this.title;
  }

  copy(overrides = {}) {
    return new Column({
      cards: this.cards,
      color: this.color,
      default_sort: this.default_sort,
      icon: this.icon,
      id: this.id,
      move_to_assigned: this.move_to_assigned,
      move_to_category_id: this.move_to_category_id,
      move_to_status: this.move_to_status,
      position: this.position,
      tag_id: this.tag_id,
      tag_name: this.tag_name,
      title: this.title,
      unicode_title: this.unicode_title,
      ...overrides,
    });
  }
}
import { tracked } from "@glimmer/tracking";
import { preloadCategories } from "../lib/boards-categories.js";
import Column from "./column.js";

export default class Board {
  static async createPayload(data) {
    await Board.preloadCategories(data);

    return {
      ...data,
      board: Board.create(data.board),
      columns: (data.columns || []).map((column) => Column.create(column)),
    };
  }

  static create(args = {}) {
    if (args instanceof Board) {
      return args;
    }
    return new Board(args);
  }

  static preloadCategories({ board, columns = [] }) {
    return preloadCategories([
      ...(board.category_ids || []),
      ...columns.flatMap((column) => [
        column.move_to_category_id,
        ...(column.cards || []).map((card) => card.topic?.category_id),
      ]),
    ]);
  }

  @tracked anonymous_can_read;
  @tracked archived;
  @tracked can_archive;
  @tracked can_manage;
  @tracked can_manage_acl_owner;
  @tracked can_unarchive;
  @tracked can_write;
  @tracked card_style;
  @tracked category_ids;
  @tracked columns;
  @tracked id;
  @tracked name;
  @tracked old_slug_used;
  @tracked owners;
  @tracked require_confirmation;
  @tracked show_tags;
  @tracked show_topic_thumbnail;
  @tracked slug;
  @tracked tag_ids;
  @tracked tag_names;
  @tracked unicode_name;

  constructor(args = {}) {
    Object.assign(this, args);
    this.columns = (args.columns || []).map((column) => Column.create(column));
  }

  get canManage() {
    return !this.archived && this.can_manage;
  }

  get canWrite() {
    return !this.archived && this.can_write;
  }

  get fancyTitle() {
    return this.unicode_name || this.name;
  }
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { fn } from "@ember/helper";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import didInsert from "@ember/render-modifiers/modifiers/did-insert";
import { service } from "@ember/service";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import DButton from "discourse/ui-kit/d-button";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import { i18n } from "discourse-i18n";
import Board from "discourse/plugins/boards/discourse/models/board";
import BoardsAddFromTopicColumnSubmenu from "./boards-add-from-topic-column-submenu.gjs";

const SKELETON_ROWS = Array.from({ length: 3 });

const BoardSkeleton = <template>
  <div
    aria-hidden="true"
    class="discourse-boards-add-from-topic-menu__skeleton"
  >
    <div class="discourse-boards-add-from-topic-menu__skeleton-label"></div>
    <div class="discourse-boards-add-from-topic-menu__skeleton-icon"></div>
  </div>
</template>;

export default class BoardsAddFromTopicMenu extends Component {
  @service menu;

  @tracked boards = [];
  @tracked loading = true;

  skeletonRows = SKELETON_ROWS;
  #requestedBoards = false;

  get availableBoards() {
    return this.boards.filter((board) => !board.topic_is_member);
  }

  get alreadyAddedBoards() {
    return this.boards.filter((board) => board.topic_is_member);
  }

  @action
  loadBoards() {
    if (this.#requestedBoards) {
      return;
    }

    this.#requestedBoards = true;
    this.#fetchBoards();
  }

  @action
  openBoardSubmenu(board, event) {
    return this.menu.show(event.currentTarget, {
      identifier: "discourse-boards-add-from-topic-column-menu",
      component: BoardsAddFromTopicColumnSubmenu,
      modalForMobile: true,
      placement: "right-start",
      offset: { mainAxis: 10, crossAxis: -5 },
      data: { board, topic: this.args.data?.topic },
      onClose: (data) => {
        if (data?.cardSaved) {
          this.args.close();
        }
      },
    });
  }

  async #fetchBoards() {
    try {
      const result = await ajax(
        `/boards/api/boards/available?topic_id=${this.args.data.topic.id}&allowed_permissions=edit,manage`
      );
      this.boards = result.boards
        .filter((board) => board.columns?.length)
        .map((board) => Board.create(board));
    } catch (error) {
      popupAjaxError(error);
    } finally {
      this.loading = false;
    }
  }

  <template>
    <DDropdownMenu
      class="discourse-boards-add-from-topic-menu"
      {{didInsert this.loadBoards}}
      as |dropdown|
    >
      {{#if this.loading}}
        {{#each this.skeletonRows}}
          <dropdown.item>
            <BoardSkeleton />
          </dropdown.item>
        {{/each}}
      {{else}}
        {{#if this.boards.length}}
          {{#if this.availableBoards.length}}
            <dropdown.subheader>
              {{i18n "boards.topic_footer.add_to_board"}}
            </dropdown.subheader>
            {{#each this.availableBoards as |board|}}
              <dropdown.item
                class="discourse-boards-add-from-topic-menu__board-item"
                {{on
                  "mouseenter"
                  (fn this.openBoardSubmenu board)
                  passive=true
                }}
              >
                <DButton
                  class="btn-transparent discourse-boards-add-from-topic-menu__board"
                  @action={{this.openBoardSubmenu}}
                  @actionParam={{board}}
                  @forwardEvent={{true}}
                  @suffixIcon="angle-right"
                  @translatedLabel={{board.fancyTitle}}
                />
              </dropdown.item>
            {{/each}}
          {{/if}}
          {{#if this.alreadyAddedBoards.length}}
            <dropdown.subheader>
              {{i18n "boards.topic_footer.already_added"}}
            </dropdown.subheader>
            {{#each this.alreadyAddedBoards as |board|}}
              <dropdown.item
                class="discourse-boards-add-from-topic-menu__board-item"
                {{on
                  "mouseenter"
                  (fn this.openBoardSubmenu board)
                  passive=true
                }}
              >
                <DButton
                  class="btn-transparent discourse-boards-add-from-topic-menu__board"
                  @action={{this.openBoardSubmenu}}
                  @actionParam={{board}}
                  @forwardEvent={{true}}
                  @suffixIcon="angle-right"
                  @translatedLabel={{board.fancyTitle}}
                />
              </dropdown.item>
            {{/each}}
          {{/if}}
        {{else}}
          <dropdown.item class="discourse-boards-add-from-topic-menu__empty">
            {{i18n "boards.topic_footer.no_boards"}}
          </dropdown.item>
        {{/if}}
      {{/if}}
    </DDropdownMenu>
  </template>
}
import { modifier } from "ember-modifier";

const DRAG_SCROLL_SKIP_SELECTOR =
  ".discourse-boards-card, button, a, input, textarea, select, [contenteditable=''], [contenteditable='true']";

const DRAG_SCROLL_MOMENTUM_FRICTION = 0.92;
const DRAG_SCROLL_MOMENTUM_MAX_PX_PER_FRAME = 4;
const DRAG_SCROLL_MOMENTUM_MIN_PX_PER_FRAME = 0.5;
const DRAG_SCROLL_VELOCITY_WINDOW_MS = 80;
const DRAG_SCROLL_MS_PER_FRAME = 1000 / 60;

export const dragToScroll = modifier((element) => {
  let activePointerId = null;
  let startX = 0;
  let startScrollLeft = 0;
  let dragStarted = false;
  let velocitySamples = [];
  let momentumFrame = null;
  let pendingMoveFrame = null;
  let latestClientX = 0;

  const cancelMomentum = () => {
    if (momentumFrame) {
      cancelAnimationFrame(momentumFrame);
      momentumFrame = null;
    }
  };

  const cancelPendingMove = () => {
    if (pendingMoveFrame) {
      cancelAnimationFrame(pendingMoveFrame);
      pendingMoveFrame = null;
    }
  };

  const pruneVelocitySamples = (now) => {
    const cutoff = now - DRAG_SCROLL_VELOCITY_WINDOW_MS;
    while (velocitySamples.length > 1 && velocitySamples[0].time < cutoff) {
      velocitySamples.shift();
    }
  };

  const recordSample = (event) => {
    velocitySamples.push({ time: event.timeStamp, x: event.clientX });
    pruneVelocitySamples(event.timeStamp);
  };

  const startMomentum = (endTime) => {
    pruneVelocitySamples(endTime);
    if (velocitySamples.length < 2) {
      return;
    }

    const oldest = velocitySamples[0];
    const newest = velocitySamples[velocitySamples.length - 1];
    const dt = newest.time - oldest.time;
    if (dt <= 0) {
      return;
    }

    const pointerVelocityPerMs = (newest.x - oldest.x) / dt;
    let velocity = -pointerVelocityPerMs * DRAG_SCROLL_MS_PER_FRAME;
    velocity = Math.max(
      Math.min(velocity, DRAG_SCROLL_MOMENTUM_MAX_PX_PER_FRAME),
      -DRAG_SCROLL_MOMENTUM_MAX_PX_PER_FRAME
    );

    if (Math.abs(velocity) < DRAG_SCROLL_MOMENTUM_MIN_PX_PER_FRAME) {
      return;
    }

    const step = () => {
      const previous = element.scrollLeft;
      element.scrollLeft = previous + velocity;
      if (element.scrollLeft === previous) {
        momentumFrame = null;
        return;
      }

      velocity *= DRAG_SCROLL_MOMENTUM_FRICTION;
      if (Math.abs(velocity) < DRAG_SCROLL_MOMENTUM_MIN_PX_PER_FRAME) {
        momentumFrame = null;
        return;
      }
      momentumFrame = requestAnimationFrame(step);
    };

    momentumFrame = requestAnimationFrame(step);
  };

  const onPointerDown = (event) => {
    cancelMomentum();

    if (event.button !== 0 || event.pointerType === "touch") {
      return;
    }
    if (event.target.closest(DRAG_SCROLL_SKIP_SELECTOR)) {
      return;
    }
    if (element.scrollWidth <= element.clientWidth) {
      return;
    }

    activePointerId = event.pointerId;
    startX = event.clientX;
    startScrollLeft = element.scrollLeft;
    dragStarted = false;
    velocitySamples = [{ time: event.timeStamp, x: event.clientX }];
  };

  const onPointerMove = (event) => {
    if (event.pointerId !== activePointerId) {
      return;
    }

    const dx = event.clientX - startX;
    if (!dragStarted) {
      if (Math.abs(dx) < 4) {
        return;
      }
      dragStarted = true;
      element.classList.add("discourse-boards-board-container--drag-scrolling");
      try {
        element.setPointerCapture(activePointerId);
      } catch {
        // pointer capture is best-effort
      }
    }

    event.preventDefault();
    latestClientX = event.clientX;
    recordSample(event);

    if (pendingMoveFrame === null) {
      pendingMoveFrame = requestAnimationFrame(() => {
        pendingMoveFrame = null;
        element.scrollLeft = startScrollLeft - (latestClientX - startX);
      });
    }
  };

  const stopDrag = (event) => {
    if (event.pointerId !== activePointerId) {
      return;
    }

    cancelPendingMove();

    const wasDragging = dragStarted;
    if (dragStarted) {
      try {
        element.releasePointerCapture(activePointerId);
      } catch {
        // pointer capture release is best-effort
      }
      element.classList.remove(
        "discourse-boards-board-container--drag-scrolling"
      );
    }

    activePointerId = null;
    dragStarted = false;

    if (wasDragging && event.type === "pointerup") {
      startMomentum(event.timeStamp);
    }
  };

  const onClickCapture = (event) => {
    if (dragStarted) {
      event.stopPropagation();
      event.preventDefault();
    }
  };

  const onWheel = () => cancelMomentum();

  element.addEventListener("pointerdown", onPointerDown);
  element.addEventListener("pointermove", onPointerMove);
  element.addEventListener("pointerup", stopDrag);
  element.addEventListener("pointercancel", stopDrag);
  element.addEventListener("click", onClickCapture, true);
  element.addEventListener("wheel", onWheel, { passive: true });

  return () => {
    cancelMomentum();
    cancelPendingMove();
    element.removeEventListener("pointerdown", onPointerDown);
    element.removeEventListener("pointermove", onPointerMove);
    element.removeEventListener("pointerup", stopDrag);
    element.removeEventListener("pointercancel", stopDrag);
    element.removeEventListener("click", onClickCapture, true);
    element.removeEventListener("wheel", onWheel);
  };
});
export const COLUMN_SORT_PRIORITY = "priority";
export const COLUMN_SORT_RECENCY = "recency";

export function isRecencyColumn(column) {
  return column?.default_sort === COLUMN_SORT_RECENCY;
}

export function cardRecencyValue(card) {
  const value = Date.parse(
    card?.recency_at ||
      card?.column_changed_at ||
      card?.updated_at ||
      card?.topic?.bumped_at ||
      card?.created_at ||
      ""
  );

  return Number.isFinite(value) ? value : 0;
}

export function sortCardsForColumn(column, cards = []) {
  const sorted = [...cards];

  if (isRecencyColumn(column)) {
    return sorted.sort(
      (a, b) =>
        cardRecencyValue(b) - cardRecencyValue(a) || (b.id || 0) - (a.id || 0)
    );
  }

  return sorted.sort(
    (a, b) => (a.position || 0) - (b.position || 0) || (a.id || 0) - (b.id || 0)
  );
}
