            @disabled={{not @model.board.canWrite}}
            @form={{form}}
            @name="title"
            @placeholder={{i18n "boards.board.title_placeholder"}}
            @showClose={{false}}
            @title={{i18n "boards.board.title"}}
          />
          <form.Section>
            <form.Field
              @disabled={{not @model.board.canWrite}}
              @format="max"
              @name="notes"
              @title={{i18n "boards.board.notes"}}
              @type="composer"
              as |field|
            >
              <field.Control
                @forceEditorMode={{USER_OPTION_COMPOSITION_MODES.rich}}
                @height={{300}}
              />
            </form.Field>
            <form.Field
              @disabled={{not @model.board.canWrite}}
              @format="max"
              @name="tags"
              @title={{i18n "boards.board.tags"}}
              @type="tag-chooser"
              as |field|
            >
              <field.Control
                @allowCreate={{true}}
                @prioritizeRecentTags={{true}}
              />
            </form.Field>

            {{#if this.siteSettings.assign_enabled}}
              <form.Field
                @disabled={{not @model.board.canWrite}}
                @format="max"
                @name="assigned_to"
                @title={{i18n "boards.board.assigned_to"}}
                @type="custom"
                as |field|
              >
                <field.Control>
                  <EmailGroupUserChooser
                    @onChange={{fn this.onAssignedChanged field}}
                    @options={{hash
                      disabled=(not @model.board.canWrite)
                      maximum=1
                      excludeCurrentUser=false
                    }}
                    @value={{data.assigned_to}}
                  />
                </field.Control>
              </form.Field>
            {{/if}}
          </form.Section>

          <form.Actions>
            {{#if @model.board.canWrite}}
              <form.Submit />
            {{/if}}
            <form.Button
              class="btn-flat d-modal-cancel"
              @action={{@closeModal}}
              @label="cancel"
