  }

  async loadFirstPost() {
    try {
      const post = await ajax(
        `/posts/by_number/${this.args.model.card.topic_id}/1.json`
      );
      this.cooked = post.cooked;
    } catch {
      this.loadError = true;
    } finally {
      this.loading = false;
    }
  }

  @action
  viewCard() {
    if (!this.currentUser) {
      return;
    }

    ajax(
      `/boards/api/boards/${this.args.model.card.board_id}/cards/${this.args.model.card.id}/view`,
      { method: "POST" }
    ).catch(() => {
      // No error message should be shown if this fails,
      // it's purely for history logging.
    });
  }

  <template>
    <DModal
      class="discourse-boards-topic-card-detail-modal"
      @closeModal={{@closeModal}}
      @title={{this.topicTitle}}
      {{didInsert this.viewCard}}
    >
      <:body>

        {{#if
          (or
            this.topic.category_id
            this.tagsHtml
            this.allAssignedUsers.length
            this.columnData
          )
        }}
          <div class="discourse-boards-topic-card-detail__meta">
            {{#if this.topic.category_id}}
              <DAsyncContent
                @asyncData={{loadCategory}}
                @context={{this.topic.category_id}}
              >
                <:content as |category|>
                  {{dCategoryBadge category link=true}}
                </:content>
              </DAsyncContent>
            {{/if}}
            {{#if this.tagsHtml}}
              <span class="discourse-boards-topic-card-detail__tags">
                {{trustHTML this.tagsHtml}}
              </span>
            {{/if}}
            {{#if this.allAssignedUsers.length}}
              <span class="discourse-boards-topic-card-detail__assigned">
                {{dIcon "user-plus"}}
                {{#each this.allAssignedUsers as |user|}}
                  <a
                    class="discourse-boards-topic-card-detail__username"
                    href="/u/{{user.username}}/activity/assigned"
                  >{{user.username}}</a>
                {{/each}}
              </span>
            {{else if this.assignedGroupName}}
              <span class="discourse-boards-topic-card-detail__assigned">
                {{dIcon "group-plus"}}
                <span
                  class="discourse-boards-topic-card-detail__username"
                >{{this.assignedGroupName}}</span>
              </span>
            {{/if}}
            {{#if this.columnData}}
              <span
                class="discourse-boards-column__title"
                style={{columnColorVariable this.columnData.color}}
              >
                {{#if this.columnData.icon}}{{dIcon
                    this.columnData.icon
                  }}{{/if}}
                {{this.columnData.title}}
              </span>
            {{/if}}
          </div>
        {{/if}}

        <DConditionalLoadingSpinner @condition={{this.loading}}>
          {{#if this.loadError}}
            <div class="discourse-boards-topic-card-detail__error">
              {{i18n "boards.board.topic_load_error"}}
            </div>
          {{else}}
            <div class="discourse-boards-topic-card-detail__cooked">
              <DDecoratedHtml
                @className="cooked"
                @html={{trustHTML this.cooked}}
              />
            </div>
          {{/if}}
        </DConditionalLoadingSpinner>

        {{#if this.replyCount}}
          <div class="discourse-boards-topic-card-detail__stats">
            {{dIcon "comments"}}
            {{i18n "boards.board.topic_reply_count" count=this.replyCount}}
            {{#if this.lastPoster}}
              <span
                class="discourse-boards-topic-card-detail__separator"
              >·</span>
              {{i18n
                "boards.board.topic_last_reply"
                username=this.lastPoster.username
              }}
              {{dFormatDate this.topic.bumped_at format="medium"}}
            {{/if}}
          </div>
        {{/if}}
      </:body>
      <:footer>
        <DButton
          class="btn-primary"
          @href={{this.topicUrl}}
          @icon="up-right-from-square"
          @label="boards.board.view_topic"
        />
      </:footer>
    </DModal>
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { fn, hash } from "@ember/helper";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import { getOwner } from "@ember/owner";
import { service } from "@ember/service";
import { trustHTML } from "@ember/template";
import { modifier } from "ember-modifier";
import TopicStatus from "discourse/components/topic-status";
import DMenu from "discourse/float-kit/components/d-menu";
import renderTags from "discourse/lib/render-tags";
import { emojiUnescape } from "discourse/lib/text";
import DiscourseURL from "discourse/lib/url";
import { escapeExpression } from "discourse/lib/utilities";
import DAsyncContent from "discourse/ui-kit/d-async-content";
import DButton from "discourse/ui-kit/d-button";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import dCategoryBadge from "discourse/ui-kit/helpers/d-category-badge";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import dFormatDate from "discourse/ui-kit/helpers/d-format-date";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { renderAvatar } from "discourse/ui-kit/helpers/d-user-avatar";
import dDragAndDropSource from "discourse/ui-kit/modifiers/d-drag-and-drop-source";
import { i18n } from "discourse-i18n";
import { loadCategory } from "../lib/boards-categories.js";
import { boardsBoardUrl, boardsCardUrl } from "../lib/boards-urls.js";
import AutoLinkedText from "./auto-linked-text.gjs";
import BoardsCardDetailModal from "./modal/boards-card-detail.gjs";
import BoardsFloaterAssignModal from "./modal/boards-floater-assign.gjs";
import BoardsTopicCardDetailModal from "./modal/boards-topic-card-detail.gjs";

export function shouldInsertSourceDropIndicator(root = document) {
  return !root.querySelector(
    ".discourse-boards-column__drop-indicator:not(.discourse-boards-column__drop-indicator--source)"
  );
}

export default class BoardsCard extends Component {
  @service currentUser;
  @service modal;
  @service siteSettings;

  @tracked dragging = false;

  /**
   * Links and images inside the card start their own native drag, which no
   * column accepts. Tags and badges are rendered HTML that can't bind
   * `draggable`, so it is switched off on whatever is pressed.
   */
  suppressNestedNativeDrag = modifier((element) => {
    const onPointerDown = (event) => {
      if (!element.hasAttribute("data-drag-source")) {
        return;
      }
      const nested = event.target.closest?.("a, img");
      if (nested && element.contains(nested)) {
        nested.draggable = false;
      }
    };

    element.addEventListener("pointerdown", onPointerDown, { capture: true });
    return () =>
      element.removeEventListener("pointerdown", onPointerDown, {
        capture: true,
      });
  });

  willDestroy() {
    super.willDestroy(...arguments);

    if (this.dragging) {
      this.#removeDropIndicators();
    }
  }

  get isTopicCard() {
    return this.args.card.card_type === "topic" && this.args.card.topic;
  }

  get topic() {
    return this.args.card.topic;
  }

  get cardTitle() {
    return this.args.card.fancyTitle;
  }

  get renderedTopicTitle() {
    return trustHTML(emojiUnescape(escapeExpression(this.cardTitle || "")));
  }

  get inlineOneboxData() {
    const data = this.args.card.inline_onebox_data;
    return data?.url && data?.title ? data : null;
  }

  get columnTagNames() {
    return new Set(
      (this.args.columnTags || []).map((tag) => tag.toLowerCase())
    );
  }

  get visibleFloaterTags() {
    const tags = this.args.card.tags || [];
    if (!tags.length) {
      return [];
    }

    const columnTagNames = this.columnTagNames;
    return tags.filter((tag) => {
      const name = typeof tag === "string" ? tag : tag.name;
      return !columnTagNames.has(name?.toLowerCase());
    });
  }

  get tagsHtml() {
    if (this.isTopicCard) {
      if (!this.args.board.show_tags || !this.topic?.tags) {
        return null;
      }

      const columnTagNames = this.columnTagNames;
      const filtered = this.topic.tags.filter(
        (tag) => !columnTagNames.has(tag.toLowerCase())
      );

      return filtered.length ? renderTags(null, { tags: filtered }) : null;
    }

    const tags = this.visibleFloaterTags;
    return tags.length ? renderTags(null, { tags }) : null;
  }

  get categoryId() {
    return this.args.allSameCategory ? null : this.topic?.category_id;
  }

  get isDetailed() {
    return this.args.board.card_style === "detailed";
  }

  get showImage() {
    return this.args.board.show_topic_thumbnail && this.topic?.image_url;
  }

  get allAssignedUsers() {
    if (this.topic?.all_assigned_users?.length) {
      return this.topic.all_assigned_users;
    }
    if (this.topic?.assigned_to_user) {
      return [this.topic.assigned_to_user];
    }
    const floaterAssignment = this.args.card.assigned_to;
    if (
      !this.isTopicCard &&
      this.siteSettings.assign_enabled &&
      floaterAssignment?.type === "User"
    ) {
      return [floaterAssignment];
    }
    return [];
  }

  get assignedGroup() {
    if (!this.siteSettings.assign_enabled) {
      return null;
    }
    const floaterAssignment = this.args.card.assigned_to;
    if (!this.isTopicCard && floaterAssignment?.type === "Group") {
      return floaterAssignment;
    }
    return null;
  }

  get assignedAvatarHtml() {
    const users = this.allAssignedUsers;
    if (!users.length) {
      return null;
    }
    return users
      .map((user) =>
        renderAvatar(user, {
          avatarTemplatePath: "avatar_template",
          usernamePath: "username",
          imageSize: "tiny",
        })
      )
      .join("");
  }

  get lastPosterUsername() {
    if (this.isTopicCard) {
      return this.topic?.last_poster?.username;
    }
    return this.args.card.created_by?.username;
  }

  get activityDate() {
    return (
      this.args.card.recency_at ||
      (this.isTopicCard ? this.topic?.bumped_at : this.args.card.created_at)
    );
  }

  get topicStatusModel() {
    if (!this.isTopicCard) {
      return null;
    }
    return { closed: this.topic?.closed };
  }

  get canShowActions() {
    return this.args.board.canWrite;
  }

  get showAssignButton() {
    if (!this.isTopicCard) {
      return this.canAssign;
    }

    return this.canAssign && !this.topicStatusModel?.closed;
  }

  get canAssign() {
    return (
      !this.args.board.archived &&
      this.siteSettings.assign_enabled &&
      this.currentUser?.can_assign &&
      (this.isTopicCard || this.args.board.canWrite)
    );
  }

  get isAssigned() {
    return (
      this.allAssignedUsers.length > 0 ||
      !!this.topic?.assigned_to_group ||
      !!this.assignedGroup
    );
  }

  get topicAssignments() {
    return (this.topic?.assignments || []).map((a) => ({
      ...a,
      unassignLabel: a.username
        ? a.target_type === "Post"
          ? i18n("boards.board.unassign_from_post", {
              username: a.username,
              post_number: a.post_number,
            })
          : i18n("boards.board.unassign_from_topic", {
              username: a.username,
            })
        : i18n("boards.board.unassign_group_from_topic", {
            group_name: a.group_name,
          }),
    }));
  }

  @action
  openDetailModal() {
    const board = this.args.board;
    const boardUrl = boardsBoardUrl(board);
    const cardUrlPath = boardsCardUrl(board, this.args.card.id);

    DiscourseURL.replaceState(cardUrlPath);

    this.modal
      .show(BoardsCardDetailModal, {
        model: {
          card: this.args.card,
          board: this.args.board,
          onUpdateCard: this.args.onUpdateCard,
        },
      })
      .finally(() => {
        if (!this.isDestroying) {
          DiscourseURL.replaceState(boardUrl);
        }
      });
  }

  @action
  openTopicDetailModal() {
    const board = this.args.board;
    const boardUrl = boardsBoardUrl(board);
    const cardUrlPath = boardsCardUrl(board, this.args.card.id);
    let navigatedAway = false;

    DiscourseURL.replaceState(cardUrlPath);

    this.modal
      .show(BoardsTopicCardDetailModal, {
        model: {
          card: this.args.card,
          columnTitle: this.args.columnTitle,
          columnIcon: this.args.columnIcon,
          columnColor: this.args.columnColor,
          onNavigateAway: (url) => {
            navigatedAway = true;
            DiscourseURL.routeTo(url);
          },
        },
      })
      .finally(() => {
        if (!navigatedAway && !this.isDestroying) {
          DiscourseURL.replaceState(boardUrl);
        }
      });
  }

  @action
  handleAssign(event) {
    event?.stopPropagation();
    if (this.isTopicCard) {
      const taskActions = getOwner(this).lookup("service:task-actions");
      taskActions.showAssignModal(this.topic, {
        isAssigned: this.isAssigned,
        targetType: "Topic",
        onSuccess: () => this.args.onRefreshBoard?.(),
      });
    } else {
      this.#openFloaterAssignModal();
    }
  }

  @action
  editAssignments(close) {
    close?.();
    if (this.isTopicCard) {
      const taskActions = getOwner(this).lookup("service:task-actions");
      taskActions.showAssignModal(this.topic, {
        isAssigned: this.isAssigned,
        targetType: "Topic",
        onSuccess: () => this.args.onRefreshBoard?.(),
      });
    } else {
      this.#openFloaterAssignModal();
    }
  }

  @action
  async unassignFromMenu(close) {
    close?.();
    if (this.isTopicCard) {
      const taskActions = getOwner(this).lookup("service:task-actions");
      await taskActions.unassign(this.topic.id, "Topic");
    } else {
      await this.args.onUpdateCard?.(this.args.card.id, {
        assigned_to_name: null,
      });
    }
    this.args.onRefreshBoard?.();
  }

  @action
  async unassignTarget(assignment, close) {
    close?.();
    const taskActions = getOwner(this).lookup("service:task-actions");
    await taskActions.unassign(assignment.target_id, assignment.target_type);
    this.args.onRefreshBoard?.();
  }

  @action
  onCardClick(event) {
    if (
      event.target.closest(".discourse-boards-card__actions-trigger") ||
      event.target.closest(".discourse-boards-card__assign-btn") ||
      event.target.closest("[data-content]") ||
      event.target.closest("a")
    ) {
      return;
    }
    if (this.isTopicCard) {
      this.openTopicDetailModal();
    } else {
      this.openDetailModal();
    }
  }

  @action
  onCardKeydown(event) {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      this.onCardClick(event);
    }
  }

  @action
  removeCard() {
    this.args.onDeleteCard(this.args.card.id);
  }

  @action
  dragStart({ source }) {
    const cardElement = source.element;
    const cardHeight = cardElement.getBoundingClientRect().height;

    this.args.onDragStart({
      cardId: this.args.card.id,
      topicId: this.args.card.topic_id,
      fromColumnId: this.args.card.column_id,
      cardHeight,
      hasPlacedIndicator: false,
    });

    if (shouldInsertSourceDropIndicator()) {
      this.#insertSourceDropIndicator(cardElement, cardHeight);
    }
    this.dragging = true;
  }

  @action
  dragEnd() {
    this.args.onDragEnd?.(this.args.card.id);
    if (!this.args.isPendingDrop) {
      this.#removeDropIndicators();
    }
    this.dragging = false;
  }

  #openFloaterAssignModal() {
    const assignedTo = this.args.card.assigned_to;
    this.modal.show(BoardsFloaterAssignModal, {
      model: {
        currentAssignee: assignedTo?.username || assignedTo?.name || null,
        onSave: async (name) => {
          await this.args.onUpdateCard?.(this.args.card.id, {
            assigned_to_name: name,
          });
          this.args.onRefreshBoard?.();
        },
      },
    });
  }

  #insertSourceDropIndicator(cardElement, cardHeight) {
    const cardsContainer = cardElement.closest(
      ".discourse-boards-column__cards"
    );
    if (!cardsContainer) {
      return;
    }

    this.#removeDropIndicators();

    const indicator = document.createElement("div");
    indicator.className =
      "discourse-boards-column__drop-indicator discourse-boards-column__drop-indicator--source";
    indicator.style.height = `${cardHeight}px`;

    cardsContainer.insertBefore(indicator, cardElement);
  }

  #removeDropIndicators() {
    document
      .querySelectorAll(".discourse-boards-column__drop-indicator")
      .forEach((indicator) => indicator.remove());
  }

  <template>
    {{! eslint-disable ember/template-no-nested-interactive }}
    <div
      class={{dConcatClass
        "discourse-boards-card"
        (if (or this.dragging @isPendingDrop) "discourse-boards-card--dragging")
        (unless this.isTopicCard "discourse-boards-card--floater")
        (if @isDropHighlighted "discourse-boards-card--drop-highlighted")
        (if @isLinkHighlighted "discourse-boards-card--link-highlighted")
      }}
      data-card-id={{@card.id}}
      data-topic-id={{@card.topic_id}}
      role="button"
      tabindex="0"
      {{dDragAndDropSource
        type="boards-card"
        data=(hash cardId=@card.id fromColumnId=@card.column_id)
        disabled=(not @board.canWrite)
        onDragEnd=this.dragEnd
        onDragStart=this.dragStart
      }}
      {{this.suppressNestedNativeDrag}}
      {{on "click" this.onCardClick}}
      {{on "keydown" this.onCardKeydown}}
    >
      <div class="discourse-boards-card__row discourse-boards-card__title-row">

        {{#if this.isTopicCard}}
          <span
            class="discourse-boards-card__title discourse-boards-card__title--topic"
          >
            {{#if this.topicStatusModel}}
              <TopicStatus @topic={{this.topicStatusModel}} />
            {{/if}}
            {{this.renderedTopicTitle}}
          </span>
        {{else}}
          <span class="discourse-boards-card__title">
            {{#if this.inlineOneboxData}}
              <a
                class={{dConcatClass
                  "inline-onebox"
                  this.inlineOneboxData.css_class
                }}
                href={{this.inlineOneboxData.url}}
                rel="noopener noreferrer"
                target="_blank"
              >{{this.inlineOneboxData.title}}</a>
            {{else}}
              <AutoLinkedText @text={{this.cardTitle}} />
            {{/if}}
          </span>
        {{/if}}
        {{#if this.canShowActions}}
          <DMenu
            @icon="ellipsis"
            @identifier="boards-card-actions"
            @triggerClass="btn-flat btn-small discourse-boards-card__actions-trigger"
          >
            <:content>
              <DDropdownMenu as |dropdown|>
                {{#unless this.isTopicCard}}
                  <dropdown.item>
                    <DButton
                      class="btn-transparent"
                      @action={{this.openDetailModal}}
                      @icon="pencil"
                      @label="edit"
                    />
                  </dropdown.item>
                  <dropdown.item>
                    <DButton
                      class="btn-transparent"
                      @action={{@onPromoteToTopic}}
                      @icon="plus"
                      @label="boards.board.new_topic"
                    />
                  </dropdown.item>
                {{/unless}}
                <dropdown.item>
                  <DButton
                    class="btn-transparent btn-danger"
                    @action={{this.removeCard}}
                    @icon="trash-can"
                    @label="boards.board.remove_card"
                  />
                </dropdown.item>
              </DDropdownMenu>
            </:content>
          </DMenu>
        {{/if}}
        {{#unless this.isDetailed}}
          {{#if this.activityDate}}
            <span class="discourse-boards-card__date">
              {{dFormatDate this.activityDate format="tiny" noTitle="true"}}
            </span>
          {{/if}}
        {{/unless}}
      </div>

      {{#if this.tagsHtml}}
        <div class="discourse-boards-card__row discourse-boards-card__tags">
          {{trustHTML this.tagsHtml}}
        </div>
      {{/if}}

      <div class="discourse-boards-card__row discourse-boards-card__meta-data">
        {{#if this.categoryId}}
          <DAsyncContent
            @asyncData={{loadCategory}}
            @context={{this.categoryId}}
          >
            <:content as |category|>
              {{#if category}}
                <div
                  class="discourse-boards-card__category discourse-boards-card__row-item"
                >
                  {{dCategoryBadge category}}
                </div>
              {{/if}}
            </:content>
          </DAsyncContent>
        {{/if}}
        {{#if this.isDetailed}}
          <div class="discourse-boards-card__row-item">
            <div class="discourse-boards-card__last-post-by">
              {{#if this.activityDate}}
                {{dFormatDate this.activityDate format="tiny" noTitle="true"}}
              {{/if}}
              {{#if this.lastPosterUsername}}
                ({{this.lastPosterUsername}})
              {{/if}}
            </div>
            {{#if this.showAssignButton}}
              <div class="discourse-boards-card__assign">
                {{#if this.isAssigned}}
                  <DMenu
                    @class="btn-flat"
                    @identifier="boards-card-assignment"
                    @triggerClass="discourse-boards-card__assign-trigger"
                  >
                    <:trigger>
                      {{#if this.assignedAvatarHtml}}
                        {{trustHTML this.assignedAvatarHtml}}
                      {{else if this.assignedGroup}}
                        {{dIcon "group"}}
                      {{/if}}
                    </:trigger>
                    <:content as |args|>
                      <DDropdownMenu as |dropdown|>
                        {{#if this.isTopicCard}}
                          {{#each this.topicAssignments as |assignment|}}
                            <dropdown.item>
                              <DButton
                                class="btn-transparent"
                                @action={{fn
                                  this.unassignTarget
                                  assignment
                                  args.close
                                }}
                                @icon="user-xmark"
                                @translatedLabel={{assignment.unassignLabel}}
                              />
                            </dropdown.item>
                          {{/each}}
                        {{else}}
                          <dropdown.item>
                            <DButton
                              class="btn-transparent"
                              @action={{fn this.unassignFromMenu args.close}}
                              @icon="user-xmark"
                              @label="boards.board.unassign"
                            />
                          </dropdown.item>
                        {{/if}}
                        <dropdown.item>
                          <DButton
                            class="btn-transparent"
                            @action={{fn this.editAssignments args.close}}
                            @icon="pencil"
                            @label="boards.board.edit_assignments"
                          />
                        </dropdown.item>
                      </DDropdownMenu>
                    </:content>
                  </DMenu>
                {{else}}
                  <DButton
                    class="btn-flat discourse-boards-card__assign-btn"
                    @action={{this.handleAssign}}
                    @icon="user-plus"
                    @title="boards.board.assign"
                  />
                {{/if}}
              </div>
            {{/if}}

          </div>
        {{/if}}

      </div>

      {{#if this.showImage}}
        <div
          class="discourse-boards-card__row discourse-boards-card__thumbnail-row"
        >
          <img
            class="discourse-boards-card__thumbnail"
            src={{this.topic.image_url}}
          />
        </div>
      {{/if}}

    </div>
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import { cancel } from "@ember/runloop";
import { isEmpty } from "@ember/utils";
import Form from "discourse/components/form";
import TopicStatus from "discourse/components/topic-status";
import discourseDebounce from "discourse/lib/debounce";
import { withoutPrefix } from "discourse/lib/get-url";
import { searchForTerm } from "discourse/lib/search";
import DiscourseURL, { TOPIC_URL_REGEXP } from "discourse/lib/url";
import DButton from "discourse/ui-kit/d-button";
import DModal from "discourse/ui-kit/d-modal";
import dCategoryLink from "discourse/ui-kit/helpers/d-category-link";
import dDiscourseTags from "discourse/ui-kit/helpers/d-discourse-tags";
import dLoadingSpinner from "discourse/ui-kit/helpers/d-loading-spinner";
import dReplaceEmoji from "discourse/ui-kit/helpers/d-replace-emoji";
import { i18n } from "discourse-i18n";

export default class BoardsAddTopicAsCard extends Component {
  @tracked selectedRow = -1;
  @tracked searchResults = [];
  @tracked searchLoading = false;
  data = { topicSearch: "" };
  #debounced;
  #activeSearch;

  willDestroy() {
    super.willDestroy(...arguments);
    cancel(this.#debounced);
  }

  highlightRow(e, direction) {
    const index =
      direction === "down" ? this.selectedRow + 1 : this.selectedRow - 1;

    if (index > -1 && index < this.searchResults.length) {
      document
        .querySelectorAll(".internal-link-results .search-link")
        [index]?.focus();
      this.selectedRow = index;
    } else {
      this.selectedRow = -1;
      document.querySelector("input.topic-search-input")?.focus();
    }

    e.preventDefault();
  }

  selectTopic(el) {
    const topicId = parseInt(el.dataset.topicId, 10);
    const title = el.dataset.title;
    if (topicId) {
      this.searchResults = [];
      this.args.model.onAddTopicAsCard({ topicId, title });
      this.args.closeModal();
    }
  }

  async triggerSearch(value) {
    const looksLikeUrl = /^(?:https?:)?\/\//i.test(value ?? "");
    if (!value || value.length < 4 || looksLikeUrl) {
      this.abortSearch();
      return;
    }

    this.searchLoading = true;
    this.#activeSearch = searchForTerm(value, { typeFilter: "topic" });

    try {
      const results = await this.#activeSearch;
      this.searchResults = results?.topics || [];
    } finally {
      this.searchLoading = false;
      this.#activeSearch = null;
    }
  }

  abortSearch() {
    this.#activeSearch?.abort();
    this.searchResults = [];
    this.searchLoading = false;
  }

  @action
  keyDown(event) {
    switch (event.key) {
      case "ArrowDown":
        this.highlightRow(event, "down");
        break;
      case "ArrowUp":
        this.highlightRow(event, "up");
        break;
      case "Enter":
        if (this.selectedRow > -1) {
          const selected = document.querySelectorAll(
            ".internal-link-results .search-link"
          )[this.selectedRow];
          if (selected) {
            this.selectTopic(selected);
          }
          event.preventDefault();
          event.stopPropagation();
        } else if (event.target.tagName === "INPUT") {
          this.formApi?.submit();
          event.preventDefault();
          event.stopPropagation();
        }
        break;
      case "Escape":
        if (this.searchResults.length) {
          this.searchResults = [];
          event.preventDefault();
          event.stopPropagation();
        }
        break;
    }
  }

  @action
  mouseDown(event) {
    if (!event.target.closest(".inputs")) {
      this.searchResults = [];
    }
  }

  @action
  topicClick(event) {
    if (!event.metaKey && !event.ctrlKey) {
      event.preventDefault();
      event.stopPropagation();
      this.selectTopic(event.target.closest(".search-link"));
    }
  }

  @action
  registerApi(api) {
    this.formApi = api;
  }

  @action
  search(value) {
    this.formApi.set("topicSearch", value);
    this.#debounced = discourseDebounce(this, this.triggerSearch, value, 400);
  }

  @action
  onFormSubmit(data) {
    const value = data.topicSearch?.trim();
    if (isEmpty(value)) {
      return;
    }

    const topicId = this.#topicIdFromInput(value);
    if (topicId) {
      this.searchResults = [];
      this.args.model.onAddTopicAsCard({ topicId, title: value });
      this.args.closeModal();
    }
  }

  #topicIdFromInput(value) {
    const input = (value ?? "").trim();
    if (!input || !DiscourseURL.isInternal(input)) {
      return null;
    }

    let pathname;
    try {
      pathname = new URL(input, DiscourseURL.origin).pathname;
    } catch {
      return null;
    }

    const stripped = withoutPrefix(pathname);
    const match = TOPIC_URL_REGEXP.exec(stripped);
    if (!match || match.index !== 0 || match[0].length !== stripped.length) {
      return null;
    }
    return parseInt(match[2], 10);
  }

  <template>
    {{! eslint-disable ember/template-no-pointer-down-event-binding }}
    <DModal
      class="discourse-boards-add-topic-as-card-modal"
      @bodyClass="insert-link"
      @closeModal={{@closeModal}}
      @title={{i18n "boards.board.add_topic_as_card"}}
      {{on "keydown" this.keyDown}}
      {{on "mousedown" this.mouseDown}}
    >
      <:body>
        <div class="inputs">
          <Form
            @data={{this.data}}
            @onRegisterApi={{this.registerApi}}
            @onSubmit={{this.onFormSubmit}}
            as |form|
          >
            <form.Field
              @format="full"
              @name="topicSearch"
              @onSet={{this.search}}
              @title={{i18n "boards.board.topic_search_placeholder"}}
              @type="input"
              as |field|
            >
              <field.Control
                autofocus="autofocus"
                class="topic-search-input"
                placeholder={{i18n "boards.board.topic_search_placeholder"}}
              />
            </form.Field>

            {{#if this.searchLoading}}
              {{dLoadingSpinner}}
            {{/if}}

            {{#if this.searchResults}}
              <div class="internal-link-results">
                {{#each this.searchResults as |result|}}
                  <a
                    class="search-link"
                    data-title={{result.fancy_title}}
                    data-topic-id={{result.id}}
                    href={{result.url}}
                    {{on "click" this.topicClick}}
                  >
                    <TopicStatus @disableActions={{true}} @topic={{result}} />
                    {{dReplaceEmoji result.title}}
                    <div class="search-category">
                      {{#if result.category.parentCategory}}
                        {{dCategoryLink result.category.parentCategory}}
                      {{/if}}
                      {{dCategoryLink result.category hideParent=true}}
                      {{dDiscourseTags result}}
                    </div>
                  </a>
                {{/each}}
              </div>
            {{/if}}
          </Form>
        </div>
      </:body>

      <:footer>
        <DButton
          class="btn-primary"
          type="submit"
          @action={{this.formApi.submit}}
          @label="boards.board.add_topic_as_card"
        />
        <DButton
          class="btn-transparent"
          @action={{@closeModal}}
          @label="cancel"
        />
      </:footer>
    </DModal>
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { fn } from "@ember/helper";
import { on } from "@ember/modifier";
import { action } from "@ember/object";
import { service } from "@ember/service";
import DMenu from "discourse/float-kit/components/d-menu";
import DButton from "discourse/ui-kit/d-button";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import dDragAndDropAutoScroll from "discourse/ui-kit/modifiers/d-drag-and-drop-auto-scroll";
import dDragAndDropTarget from "discourse/ui-kit/modifiers/d-drag-and-drop-target";
import { i18n } from "discourse-i18n";
import { isRecencyColumn } from "../lib/boards-card-ordering.js";
import {
  columnColorVariable,
  hasColumnColor,
} from "../lib/boards-column-helpers.js";
import { animateCardReorder, captureCardRects } from "../lib/boards-motion.js";
import BoardsCard from "./boards-card.gjs";
import BoardsAddTopicAsCardModal from "./modal/boards-add-topic-as-card.gjs";
import BoardsCardDetailModal from "./modal/boards-card-detail.gjs";

const RECENCY_WINDOW_MS = 7 * 24 * 60 * 60 * 1000;

export function recencyTimestamp(card) {
  const value = Date.parse(card?.recency_at || "");
  return Number.isFinite(value) ? value : 0;
}

export function recencyDropIndicatorInsertBefore(
  cardsContainer,
  cardElements,
  draggedCardId
) {
  return (
    cardElements.find((cardEl) => {
      const elCardId = parseInt(cardEl.dataset.cardId, 10);
      return elCardId !== draggedCardId;
    }) || cardsContainer.querySelector(".discourse-boards-column__show-all")
  );
}

export function shouldAnimateDropIndicatorPlacement({
  hadIndicator,
  columnId,
  fromColumnId,
  hasPlacedIndicator,
}) {
  return hadIndicator || columnId !== fromColumnId || hasPlacedIndicator;
}

export default class BoardsColumn extends Component {
  @service modal;

  @tracked showAllCards = false;

  get cardCount() {
    return this.args.column.cards?.length || 0;
  }

  get visibleCards() {
    const cards = this.args.column.cards || [];
    if (!this.isRecencySorted || this.showAllCards) {
      return cards;
    }

    const cutoff = Date.now() - RECENCY_WINDOW_MS;
    return cards.filter(
      (card) =>
        card.id === this.args.linkedCardId || recencyTimestamp(card) >= cutoff
    );
  }

  get hiddenCardCount() {
    if (!this.isRecencySorted || this.showAllCards) {
      return 0;
    }

    return this.cardCount - this.visibleCards.length;
  }

  get isRecencySorted() {
    return isRecencyColumn(this.args.column);
  }

  get columnTags() {
    const allColumns = this.args.allColumns || [];
    return allColumns.map((col) => col.tag_name).filter(Boolean);
  }

  get columnIndex() {
    const allColumns = this.args.allColumns || [];
    return allColumns.findIndex((col) => col.id === this.args.column.id);
  }

  get lastColumnIndex() {
    return (this.args.allColumns?.length || 0) - 1;
  }

  @action
  showAllOlderCards() {
    this.showAllCards = true;
  }

  @action
  async startAddCard(closeMenu) {
    await closeMenu();
    this.modal.show(BoardsCardDetailModal, {
      model: {
        card: {},
        isNew: true,
        board: this.args.board,
        onCreateCard: (data) =>
          this.args.onAddCard({ ...data, columnId: this.args.column.id }),
      },
    });
  }

  @action
  async addTopicAsCard(closeMenu) {
    await closeMenu();
    this.modal.show(BoardsAddTopicAsCardModal, {
      model: {
        onAddTopicAsCard: (data) =>
          this.args.onAddCard({ ...data, columnId: this.args.column.id }),
      },
    });
  }

  @action
  editColumn(closeMenu) {
    closeMenu();
    this.args.onEditColumn(this.args.column.id);
  }

  @action
  moveLeft(closeMenu) {
    closeMenu();
    this.args.onMoveColumn(this.args.column.id, -1);
  }

  @action
  moveRight(closeMenu) {
    closeMenu();
    this.args.onMoveColumn(this.args.column.id, 1);
  }

  @action
  clearColumn(closeMenu) {
    closeMenu();
    this.args.onClearColumn(this.args.column.id);
  }

  @action
  deleteColumn(closeMenu) {
    closeMenu();
    this.args.onDeleteColumn(this.args.column);
  }

  @action
  canDropCard({ source }) {
    // Recency columns sort themselves, so reordering within one is meaningless.
    return !(
      this.isRecencySorted && source.data.fromColumnId === this.args.column.id
    );
  }

  @action
  dragOver({ element, location }) {
    const dragData = this.args.dragData;
    if (!dragData) {
      return;
    }

    element.classList.add("discourse-boards-column--drag-target");

    const cardsContainer = element.querySelector(
      ".discourse-boards-column__cards"
    );
    if (!cardsContainer) {
      return;
    }

    const { clientY } = location.current.input;

    let indicator = cardsContainer.querySelector(
      ".discourse-boards-column__drop-indicator"
    );
    const hadIndicator = !!indicator;
    if (!indicator) {
      indicator = document.createElement("div");
      indicator.className = "discourse-boards-column__drop-indicator";
    }
    indicator.style.height = `${dragData.cardHeight}px`;

    const cardElements = [
      ...cardsContainer.querySelectorAll(".discourse-boards-card"),
    ];
    let insertBefore = null;

    if (this.isRecencySorted) {
      insertBefore = recencyDropIndicatorInsertBefore(
        cardsContainer,
        cardElements,
        dragData.cardId
      );
    } else {
      for (const cardEl of cardElements) {
        const elCardId = parseInt(cardEl.dataset.cardId, 10);
        if (elCardId === dragData.cardId) {
          continue;
        }
        const rect = cardEl.getBoundingClientRect();
        if (clientY <= rect.top + rect.height / 2) {
          insertBefore = cardEl;
          break;
        }
      }
    }

    const emptyMsg = cardsContainer.querySelector(
      ".discourse-boards-column__empty"
    );
    if (emptyMsg) {
      emptyMsg.hidden = true;
    }

    if (
      this.#indicatorMatchesPosition(cardsContainer, indicator, insertBefore)
    ) {
      return;
    }

    const shouldAnimate = shouldAnimateDropIndicatorPlacement({
      hadIndicator,
      columnId: this.args.column.id,
      fromColumnId: dragData.fromColumnId,
      hasPlacedIndicator: dragData.hasPlacedIndicator,
    });

    const previousRects = shouldAnimate
      ? captureCardRects(cardsContainer, {
          skipCardIds: [dragData.cardId],
        })
      : null;

    indicator.classList.remove(
      "discourse-boards-column__drop-indicator--source"
    );

    if (insertBefore) {
      cardsContainer.insertBefore(indicator, insertBefore);
    } else {
      cardsContainer.appendChild(indicator);
    }

    if (shouldAnimate) {
      animateCardReorder(cardsContainer, previousRects, {
        skipCardIds: [dragData.cardId],
      });
    }

    dragData.hasPlacedIndicator = true;
  }

  @action
  dragLeave({ element }) {
    element.classList.remove("discourse-boards-column--drag-target");
    this.removeDropIndicator(element, { animate: true });
  }

  @action
  drop({ element, location }) {
    element.classList.remove("discourse-boards-column--drag-target");

    const dragData = this.args.dragData;
    if (!dragData) {
      this.removeDropIndicator(element, { animate: false });
      return;
    }

    const cardsContainer = element.querySelector(
      ".discourse-boards-column__cards"
    );
    const { clientY } = location.current.input;
    let afterCardId = null;

    if (cardsContainer && !this.isRecencySorted) {
      const cardElements = [
        ...cardsContainer.querySelectorAll(".discourse-boards-card"),
      ];
      for (const cardEl of cardElements) {
        const elCardId = parseInt(cardEl.dataset.cardId, 10);
        if (elCardId === dragData.cardId) {
          continue;
        }
        const rect = cardEl.getBoundingClientRect();
        if (clientY > rect.top + rect.height / 2) {
          afterCardId = elCardId;
        }
      }
    }

    // The board viewer removes the placeholder once the move settles.
    this.args.onDrop(
      dragData.cardId,
      this.args.column.id,
      afterCardId,
      dragData.fromColumnId
    );
  }

  removeDropIndicator(columnEl, { animate = false } = {}) {
    const cardsContainer = columnEl.querySelector(
      ".discourse-boards-column__cards"
    );
    const indicator = columnEl.querySelector(
      ".discourse-boards-column__drop-indicator"
    );
    const dragData = this.args.dragData;

    if (!indicator) {
      columnEl
        .querySelector(".discourse-boards-column__empty")
        ?.removeAttribute("hidden");
      return;
    }

    const previousRects =
      animate && cardsContainer
        ? captureCardRects(cardsContainer, {
            skipCardIds: dragData ? [dragData.cardId] : [],
          })
        : null;

    indicator.remove();

    const emptyMsg = columnEl.querySelector(".discourse-boards-column__empty");
    if (emptyMsg) {
      emptyMsg.hidden = false;
    }

    if (cardsContainer && previousRects) {
      animateCardReorder(cardsContainer, previousRects, {
        skipCardIds: dragData ? [dragData.cardId] : [],
      });
    }
  }

  #indicatorMatchesPosition(cardsContainer, indicator, insertBefore) {
    if (indicator.parentElement !== cardsContainer) {
      return false;
    }

    if (insertBefore) {
      return indicator.nextElementSibling === insertBefore;
    }

    return indicator === cardsContainer.lastElementChild;
  }

  <template>
    <div
      class="discourse-boards-column
        {{if
          (hasColumnColor @column.color)
          'discourse-boards-column--has-color'
        }}"
      data-column-id={{@column.id}}
      data-default-sort={{@column.default_sort}}
      style={{columnColorVariable @column.color}}
      {{dDragAndDropTarget
        accepts="boards-card"
        canDrop=this.canDropCard
        indicator=false
        onDrag=this.dragOver
        onDragEnter=this.dragOver
        onDragLeave=this.dragLeave
        onDrop=this.drop
      }}
    >
      <div class="discourse-boards-column__header">
        <span class="discourse-boards-column__header-content">
          <span class="discourse-boards-column__title">
            {{#if @column.icon}}{{dIcon @column.icon}}{{/if}}
            {{@column.fancyTitle}}
          </span>
          <span class="discourse-boards-column__count">
            {{this.cardCount}}
          </span>
        </span>
        {{#if @board.canManage}}
          <DMenu
            @icon="ellipsis"
            @identifier="boards-column-controls"
            @title="boards.board.column_controls"
            @triggerClass="btn-flat btn-small discourse-boards-column__menu-trigger"
          >
            <:content as |args|>
              <DDropdownMenu as |dropdown|>
                <dropdown.item>
                  <DButton
                    class="btn-transparent discourse-boards-column__menu-edit"
                    @action={{fn this.editColumn args.close}}
                    @icon="pencil"
                    @label="boards.board.edit_column"
                  />
                </dropdown.item>
                <dropdown.item>
                  <DButton
                    class="btn-transparent discourse-boards-column__menu-move-left"
                    @action={{fn this.moveLeft args.close}}
                    @disabled={{eq this.columnIndex 0}}
                    @icon="arrow-left"
                    @label="boards.board.move_left"
                  />
                </dropdown.item>
                <dropdown.item>
                  <DButton
                    class="btn-transparent discourse-boards-column__menu-move-right"
                    @action={{fn this.moveRight args.close}}
                    @disabled={{eq this.columnIndex this.lastColumnIndex}}
                    @icon="arrow-right"
                    @label="boards.board.move_right"
                  />
                </dropdown.item>
                <dropdown.item>
                  <DButton
                    class="btn-transparent discourse-boards-column__menu-clear"
                    @action={{fn this.clearColumn args.close}}
                    @disabled={{eq this.cardCount 0}}
                    @icon="xmark"
                    @label="boards.board.clear_column"
                  />
                </dropdown.item>
                <dropdown.item>
                  <DButton
                    class="btn-transparent btn-danger discourse-boards-column__menu-delete"
                    @action={{fn this.deleteColumn args.close}}
                    @icon="trash-can"
                    @label="boards.board.delete_column"
                  />
                </dropdown.item>
              </DDropdownMenu>
            </:content>
          </DMenu>
        {{/if}}
      </div>

      <div
        class="discourse-boards-column__cards"
        {{dDragAndDropAutoScroll types="boards-card"}}
      >
        {{#if this.visibleCards.length}}
          {{#each this.visibleCards key="id" as |card|}}
            <BoardsCard
              @allSameCategory={{@allSameCategory}}
              @board={{@board}}
              @card={{card}}
              @columnColor={{@column.color}}
              @columnIcon={{@column.icon}}
              @columnTags={{this.columnTags}}
              @columnTitle={{@column.fancyTitle}}
              @isDropHighlighted={{eq @dropHighlightCardId card.id}}
              @isLinkHighlighted={{eq @linkHighlightCardId card.id}}
              @isPendingDrop={{eq @pendingDropCardId card.id}}
              @onDeleteCard={{@onDeleteCard}}
              @onDragEnd={{@onDragEnd}}
              @onDragStart={{@onDragStart}}
              @onPromoteToTopic={{fn @onPromoteToTopic card.id}}
              @onRefreshBoard={{@onRefreshBoard}}
              @onUpdateCard={{@onUpdateCard}}
            />
          {{/each}}
        {{else if (eq this.cardCount 0)}}
          <div class="discourse-boards-column__empty">
            {{i18n "boards.board.no_cards"}}
          </div>
        {{/if}}

        {{#if this.hiddenCardCount}}
          <button
            class="discourse-boards-column__show-all"
            type="button"
            {{on "click" this.showAllOlderCards}}
          >
            {{i18n "boards.board.show_older_cards" count=this.hiddenCardCount}}
          </button>
        {{/if}}
      </div>

      {{#if @board.canWrite}}
        <div class="discourse-boards-column__footer">
          <DMenu
            @icon="plus"
            @identifier="boards-column-add"
            @label={{i18n "boards.board.add_card"}}
            @triggerClass="discourse-boards-column__add-btn"
          >
            <:content as |args|>
              <DDropdownMenu as |dropdown|>
                <dropdown.item>
                  <DButton
                    class="btn-transparent"
                    @action={{fn this.startAddCard args.close}}
                    @icon="plus"
                    @label="boards.board.add_card"
                  />
                </dropdown.item>
                <dropdown.item>
                  <DButton
                    class="btn-transparent"
                    @action={{fn this.addTopicAsCard args.close}}
                    @icon="link"
                    @label="boards.board.add_topic_as_card"
                  />
                </dropdown.item>
              </DDropdownMenu>
            </:content>
          </DMenu>
        </div>
      {{/if}}
    </div>
  </template>
}
import Component from "@glimmer/component";
import { action } from "@ember/object";
import { service } from "@ember/service";
import { trustHTML } from "@ember/template";
import Form from "discourse/components/form";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import getURL from "discourse/lib/get-url";
import DModal from "discourse/ui-kit/d-modal";
import { i18n } from "discourse-i18n";

export default class BoardsArchive extends Component {
  @service messageBus;

  formData = { slug: "" };
  currentlyArchived = this.args.model.board.archived;

  get isUnarchive() {
    return this.currentlyArchived;
  }

  get title() {
    return i18n(
      this.isUnarchive
        ? "boards.board.unarchive_board"
        : "boards.board.archive_board"
    );
  }

  get message() {
    if (this.isUnarchive) {
      return i18n(
        this.args.model.board.old_slug_used
          ? "boards.board.unarchive_slug_required"
          : "boards.board.confirm_unarchive"
      );
    }
    return trustHTML(
      i18n("boards.board.confirm_archive", { boards_url: getURL("/boards") })
    );
  }

  @action
  async submit(data) {
    const board = this.args.model.board;
    const actionName = this.isUnarchive ? "unarchive" : "archive";
    try {
      const result = await ajax(
        `/boards/api/boards/${board.id}/${actionName}`,
        {
          type: "POST",
          data: {
            client_id: this.messageBus.clientId,
            ...(this.isUnarchive ? { slug: data.slug } : {}),
          },
        }
      );
      await this.args.model.onSuccess(result.board);
      this.args.closeModal();
    } catch (error) {
      if (this.isUnarchive) {
        const result = await ajax(`/boards/api/boards/${board.id}.json`).catch(
          () => null
        );
        if (result?.board) {
          Object.assign(board, result.board);
        }
      }
      popupAjaxError(error);
    }
  }

  <template>
    <DModal
      class="discourse-boards-archive-modal"
      @closeModal={{@closeModal}}
      @inline={{@inline}}
      @title={{this.title}}
    >
      <:body>
        <Form @data={{this.formData}} @onSubmit={{this.submit}} as |form|>
          <p>{{this.message}}</p>
          {{#if this.isUnarchive}}
            {{#if @model.board.old_slug_used}}
              <form.Field
                @name="slug"
                @required={{true}}
                @title={{i18n "boards.manage.slug"}}
                @type="input"
                as |field|
              >
                <field.Control />
              </form.Field>
            {{/if}}
          {{/if}}
          <form.Actions>
            <form.Submit @label="confirm_button" />
            <form.Button @action={{@closeModal}} @label="cancel" />
          </form.Actions>
        </Form>
      </:body>
    </DModal>
  </template>
}
import Component from "@glimmer/component";
import { cached, tracked } from "@glimmer/tracking";
import { fn } from "@ember/helper";
import { action } from "@ember/object";
import { cancel } from "@ember/runloop";
import { service } from "@ember/service";
import { isEmpty } from "@ember/utils";
import Form from "discourse/components/form";
import { ajax } from "discourse/lib/ajax";
import { popupAjaxError } from "discourse/lib/ajax-error";
import discourseDebounce from "discourse/lib/debounce";
import { slugify } from "discourse/lib/utilities";
import CategorySelector from "discourse/select-kit/components/category-selector";
import DAsyncContent from "discourse/ui-kit/d-async-content";
import DButton from "discourse/ui-kit/d-button";
import DModal from "discourse/ui-kit/d-modal";
import { i18n } from "discourse-i18n";
import { buildDefaultBoardAcl } from "../../lib/boards-access-control.js";
import { loadCategories } from "../../lib/boards-categories.js";
import BoardsAccessControlField from "../boards-access-control-field.gjs";
import BoardsEditableTitle from "../boards-editable-title.gjs";

const CONSTRAINT_TYPE_OPTIONS = [
  {
    id: "categories",
    name: i18n("boards.manage.constraint_categories"),
  },
  { id: "tags", name: i18n("boards.manage.constraint_tags") },
  {
    id: "categories_and_tags",
    name: i18n("boards.manage.constraint_categories_and_tags"),
  },
];

function inferConstraintType(categoryIds, tagNames) {
  const hasCats = categoryIds?.length > 0;
  const hasTags = tagNames?.length > 0;
  if (hasCats && hasTags) {
    return "categories_and_tags";
  } else if (hasCats) {
    return "categories";
  } else if (hasTags) {
    return "tags";
  }
  return null;
}

const CARD_STYLE_OPTIONS = [
  {
    id: "detailed",
    name: i18n("boards.manage.card_style_detailed"),
  },
  { id: "simple", name: i18n("boards.manage.card_style_simple") },
];

export default class BoardsBoardSettings extends Component {
  @service dialog;
  @service site;
  @service siteSettings;

  @tracked showAdvanced = false;

  constraintWarning = null;
  reloadAfterSave = false;

  willDestroy() {
    super.willDestroy(...arguments);
    cancel(this._constraintCheckTimer);
  }

  @cached
  get formData() {
    const board = this.args.model.board || {
      show_tags: true,
      acl: buildDefaultBoardAcl(this.site, this.siteSettings),
    };

    return {
      name: board.name || "",
      slug: board.slug || "",
      constraint_type: inferConstraintType(board.category_ids, board.tag_names),
      category_ids: board.category_ids || [],
      tag_names: board.tag_names || [],
      card_style: board.card_style || "detailed",
      show_tags: board.show_tags ?? false,
      show_topic_thumbnail: board.show_topic_thumbnail ?? false,
      require_confirmation: board.require_confirmation ?? false,
      acl: board.acl,
    };
  }

  get isNew() {
    return this.args.model.isNew;
  }

  get slugPlaceholder() {
    const boardName = this.formApi.get("name");

    if (isEmpty(boardName)) {
      return "";
    }

    return slugify(boardName);
  }

  @action
  toggleAdvanced() {
    this.showAdvanced = !this.showAdvanced;
  }

  @action
  onConstraintTypeChange(type, { set }) {
    set("constraint_type", type);
    if (!type) {
      set("category_ids", []);
      set("tag_names", []);
    } else if (type === "categories") {
      set("tag_names", []);
    } else if (type === "tags") {
      set("category_ids", []);
    }
    this._checkConstraints(
      type === "tags" || !type ? [] : null,
      type === "categories" || !type ? [] : null
    );
  }

  @action
  onCategoriesChange(field, categories) {
    const ids = categories?.map((c) => c.id) || [];
    field.set(ids);
    this._checkConstraints(ids, null);
  }

  @action
  onTagsChange(tags, { set }) {
    const names = tags.map((t) => (typeof t === "string" ? t : t.name));
    set("tag_names", names);
    this._checkConstraints(null, names);
  }

  @action
  onRegisterApi(api) {
    this.formApi = api;
  }

  @action
  async save(data) {
    if (this.constraintWarning) {
      this.dialog.confirm({
        message: this.constraintWarning,
        didConfirm: () => this._performSave(data),
      });
      return;
    }

    await this._performSave(data);
  }

  @action
  onDelete() {
    this.args.model.onDelete();
    this.args.closeModal();
  }

  @action
  aclChanged(acl) {
    this.reloadAfterSave = false;
    this.formApi.set("acl", acl);
  }

  @action
  accessLossConfirmed() {
    this.reloadAfterSave = true;
  }

  _checkConstraints(categoryIds, tagNames) {
    if (this.isNew) {
      return;
    }
    cancel(this._constraintCheckTimer);
    this._constraintCheckTimer = discourseDebounce(
      this,
      this._fetchConstraintPreview,
      categoryIds,
      tagNames,
      500
    );
  }

  async _fetchConstraintPreview(categoryIds, tagNames) {
    const boardId = this.args.model.board?.id;
    if (!boardId) {
      return;
    }

    try {
      const result = await ajax(
        `/boards/api/boards/${boardId}/constraint-preview`,
        {
          type: "POST",
          data: {
            category_ids: categoryIds ?? this.formApi?.get("category_ids"),
            tag_names: tagNames ?? this.formApi?.get("tag_names"),
          },
        }
      );
      this.constraintWarning =
        result.cards_to_remove > 0
          ? i18n("boards.manage.constraint_warning", {
              count: result.cards_to_remove,
            })
          : null;
    } catch {
      this.constraintWarning = null;
    }
  }

  async _performSave(data) {
    try {
      const aclEntries = data.acl || [];
      const ownerUserIds = aclEntries
        .filter(
          (entry) => entry.type === "user" && entry.permission === "owner"
        )
        .map((entry) => entry.id);
      const acl = aclEntries.filter((entry) => entry.permission !== "owner");
      const boardData = { ...data, acl };

      if (!this.isNew && this.args.model.board.can_manage_acl_owner) {
        boardData.owner_user_ids = ownerUserIds;
      }

      await this.args.model.onSave(boardData);
      this.args.closeModal({ reloadAfterSave: this.reloadAfterSave });
    } catch (error) {
      popupAjaxError(error);
    }
  }

  <template>
    <DModal
      class="discourse-boards-board-settings-modal"
      @closeModal={{@closeModal}}
      @hideHeader={{true}}
      @inline={{@inline}}
    >
      <:body>
        <Form
          @data={{this.formData}}
          @onRegisterApi={{this.onRegisterApi}}
          @onSubmit={{this.save}}
          as |form data|
        >
          <BoardsEditableTitle
            @form={{form}}
            @name="name"
            @onClose={{@closeModal}}
            @placeholder={{i18n "boards.manage.name_placeholder"}}
            @showClose={{true}}
            @title={{i18n "boards.manage.name"}}
          />
          <div class="discourse-boards-board-settings-modal__wrapper">

            <form.Section>
              <form.Field
                @format="max"
                @name="slug"
                @placeholder={{this.slugPlaceholder}}
                @title={{i18n "boards.manage.slug"}}
                @type="input"
                as |field|
              >
                <field.Control />
              </form.Field>
            </form.Section>

            <form.Section>
              <BoardsAccessControlField
                @boardId={{@model.board.id}}
                @canManageOwners={{or
                  this.isNew
                  @model.board.can_manage_acl_owner
                }}
                @description={{i18n "boards.manage.board_access_description"}}
                @form={{form}}
                @isNew={{this.isNew}}
                @onAccessLossConfirmed={{this.accessLossConfirmed}}
                @onChange={{this.aclChanged}}
                @title={{i18n "boards.manage.board_access"}}
              />
            </form.Section>

            <form.Section>
              <form.Field
                @description={{i18n "boards.manage.constraint_help"}}
                @format="max"
                @name="constraint_type"
                @onSet={{this.onConstraintTypeChange}}
                @title={{i18n "boards.manage.constrain_board_by"}}
                @type="select"
                as |field|
              >
                <field.Control as |select|>
                  {{#each CONSTRAINT_TYPE_OPTIONS as |option|}}
                    <select.Option
                      @value={{option.id}}
                    >{{option.name}}</select.Option>
                  {{/each}}
                </field.Control>
              </form.Field>

              {{#if
                (or
                  (eq data.constraint_type "categories")
                  (eq data.constraint_type "categories_and_tags")
                )
              }}
                <form.Field
                  @format="max"
                  @name="category_ids"
                  @title={{i18n "boards.manage.board_categories_constraint"}}
                  @type="custom"
                  as |field|
                >
                  <field.Control>
                    <DAsyncContent
                      @asyncData={{loadCategories}}
                      @context={{data.category_ids}}
                    >
                      <:content as |categories|>
                        <CategorySelector
                          @categories={{categories}}
                          @onChange={{fn this.onCategoriesChange field}}
                        />
                      </:content>
                    </DAsyncContent>
                  </field.Control>
                </form.Field>
              {{/if}}

              {{#if
                (or
                  (eq data.constraint_type "tags")
                  (eq data.constraint_type "categories_and_tags")
                )
              }}
                <form.Field
                  @format="max"
                  @name="tag_names"
                  @onSet={{this.onTagsChange}}
                  @title={{i18n "boards.manage.board_tags_constraint"}}
                  @type="tag-chooser"
                  as |field|
                >
                  <field.Control
                    @allowCreate={{true}}
                    @excludeSynonyms={{true}}
                    @showAllTags={{true}}
                  />
                </form.Field>
              {{/if}}

              {{#if this.constraintWarning}}
                <form.Alert @type="warning">
                  {{this.constraintWarning}}
                </form.Alert>
              {{/if}}
            </form.Section>
            <form.Section>
              <form.Field
                @description={{i18n "boards.manage.card_style_description"}}
                @format="max"
                @name="card_style"
                @title={{i18n "boards.manage.card_style"}}
                @type="select"
                as |field|
              >
                <field.Control as |select|>
                  {{#each CARD_STYLE_OPTIONS as |option|}}
                    <select.Option
                      @value={{option.id}}
                    >{{option.name}}</select.Option>
                  {{/each}}
                </field.Control>
              </form.Field>

            </form.Section>

            {{#if this.showAdvanced}}
              <form.Section @title={{i18n "boards.manage.advanced_settings"}}>

                <form.Field
                  @name="show_tags"
                  @title={{i18n "boards.manage.show_tags"}}
                  @type="checkbox"
                  as |field|
                >
                  <field.Control />
                </form.Field>

                <form.Field
                  @name="show_topic_thumbnail"
                  @title={{i18n "boards.manage.show_topic_thumbnail"}}
                  @type="checkbox"
                  as |field|
                >
                  <field.Control />
                </form.Field>

                <form.Field
                  @name="require_confirmation"
                  @title={{i18n "boards.manage.require_confirmation"}}
                  @type="checkbox"
                  as |field|
                >
                  <field.Control />
                </form.Field>
              </form.Section>
            {{/if}}
          </div>

          <form.Actions>
            <form.Submit
              class="discourse-boards-board-settings-modal__save-board"
            />
            {{#unless this.isNew}}
              <form.Button
                class="btn-danger discourse-boards-board-settings-modal__delete-board"
                @action={{this.onDelete}}
                @label="boards.board.delete_board"
              />
            {{/unless}}

            <DButton
              class="btn-default show-advanced"
              @action={{this.toggleAdvanced}}
              @icon="gear"
              @title={{if
                this.showAdvanced
                "boards.manage.columns.hide_advanced"
                "boards.manage.columns.show_advanced"
              }}
            />
          </form.Actions>
        </Form>

      </:body>
    </DModal>
  </template>
}
import Component from "@glimmer/component";
import { cached, tracked } from "@glimmer/tracking";
import { fn, hash } from "@ember/helper";
import { action } from "@ember/object";
import { isEmpty } from "@ember/utils";
import Form from "discourse/components/form";
import { popupAjaxError } from "discourse/lib/ajax-error";
import CategoryChooser from "discourse/select-kit/components/category-chooser";
import ComboBox from "discourse/select-kit/components/combo-box";
import EmailGroupUserChooser from "discourse/select-kit/components/email-group-user-chooser";
import MiniTagChooser from "discourse/select-kit/components/mini-tag-chooser";
import DButton from "discourse/ui-kit/d-button";
import DModal from "discourse/ui-kit/d-modal";
import { i18n } from "discourse-i18n";
import {
  ASSIGNED_OPTIONS,
  assignedMode,
  assignedUserValue,
  COLUMN_SORT_OPTIONS,
  PRESET_COLUMN_COLORS,
  STATUS_OPTIONS,
  tagToArray,
} from "../../lib/boards-column-helpers.js";
import BoardsEditableTitle from "../boards-editable-title.gjs";

export default class BoardsColumnSettings extends Component {
  @tracked showAdvanced = false;

  @cached
  get formData() {
    const column = this.args.model.column;
    return {
      title: column?.title || "",
      icon: column?.icon || null,
      color: column?.color || null,
      default_sort: column?.default_sort || "priority",
      tag_name: column?.tag_name || "",
      move_to_category_id: column?.move_to_category_id || null,
      move_to_assigned: column?.move_to_assigned || "",
      move_to_status: column?.move_to_status || "",
    };
  }

  // NOTE: We are aware this is not ideal because a board
  // can have multiple categories, but we only support one
  // for now because server-side the tag search is limited
  // to one category at a time.
  get tagChooserCategoryId() {
    return this.args.model.board?.category_ids?.[0] || null;
  }

  get showMoveToCategoryField() {
    const boardCategoryCount = this.args.model.board?.category_ids?.length ?? 0;
    if (boardCategoryCount === 1) {
      return !!this.args.model.column?.move_to_category_id;
    }
    return true;
  }

  @action
  onDefaultSortChange(field, value) {
    field.set(value || "priority");
  }

  @action
  onTagChange(field, tags) {
    const tag = tags?.[0];
    field.set(typeof tag === "object" ? tag.name : tag || "");
  }

  @action
  onCategoryChange(field, value) {
    field.set(value);
  }

  @action
  onAssignedModeChange(field, value) {
    field.set(value || "");
  }

  @action
  onAssignedUserChange(field, users) {
    field.set(users?.[0] || "_user");
  }

  @action
  onStatusChange(field, value) {
    field.set(value);
  }

  @action
  toggleAdvanced() {
    this.showAdvanced = !this.showAdvanced;
  }

  @action
  async save(data) {
    const columnData = {
      title: data.title.trim() || data.tag_name.trim(),
      icon: data.icon,
      color: data.color || null,
      default_sort: data.default_sort || "priority",
      tag_name: data.tag_name || null,
      move_to_category_id: data.move_to_category_id,
      move_to_assigned: data.move_to_assigned,
      move_to_status: data.move_to_status,
    };
    try {
      await this.args.model.onSave(columnData);
      this.args.closeModal();
    } catch (error) {
      popupAjaxError(error);
    }
  }

  @action
  validateTitle(name, value, { data, addError }) {
    if (isEmpty(value) && isEmpty(data.tag_name)) {
      addError("title", {
        title: i18n("boards.manage.columns.column_title"),
        message: i18n("boards.manage.columns.column_title_required"),
      });
    }
  }

  <template>
    <DModal
      class="discourse-boards-column-settings-modal"
      @closeModal={{@closeModal}}
      @hideHeader={{true}}
    >
      <:body>
        <Form @data={{this.formData}} @onSubmit={{this.save}} as |form data|>
          <BoardsEditableTitle
            @form={{form}}
            @name="title"
            @onClose={{@closeModal}}
            @placeholder={{i18n
              "boards.manage.columns.column_title_placeholder"
            }}
            @title={{i18n "boards.manage.columns.column_title"}}
            @validate={{this.validateTitle}}
          />
          <div class="discourse-boards-column-settings-modal__wrapper">
            <form.Section>
              <form.Field
                @format="max"
                @name="icon"
                @title={{i18n "boards.manage.columns.icon"}}
                @type="icon"
                as |field|
              >
                <field.Control />
              </form.Field>

              <form.Field
                @format="max"
                @name="color"
                @title={{i18n "boards.manage.columns.color"}}
                @type="color"
                as |field|
              >
                <field.Control @colors={{PRESET_COLUMN_COLORS}} />
              </form.Field>

              <form.Field
                @format="max"
                @name="default_sort"
                @title={{i18n "boards.manage.columns.default_sort"}}
                @type="custom"
                as |field|
              >
                <field.Control>
                  <ComboBox
                    @content={{COLUMN_SORT_OPTIONS}}
                    @onChange={{fn this.onDefaultSortChange field}}
                    @value={{data.default_sort}}
                  />
                </field.Control>
              </form.Field>

              <form.Field
                @format="max"
                @name="tag_name"
                @title={{i18n "boards.manage.columns.tag"}}
                @type="custom"
                as |field|
              >
                <field.Control>
                  <MiniTagChooser
                    @onChange={{fn this.onTagChange field}}
                    @options={{hash
                      maximum=1
                      allowCreate=true
                      categoryId=this.tagChooserCategoryId
                    }}
                    @value={{tagToArray data.tag_name}}
                  />
                  <p class="discourse-boards-column-settings__help">
                    {{i18n "boards.manage.columns.tag_help"}}
                  </p>
                </field.Control>
              </form.Field>

              <form.Field
                @format="max"
                @name="move_to_status"
                @title={{i18n "boards.manage.columns.move_to_status"}}
                @type="custom"
                as |field|
              >
                <field.Control>
                  <ComboBox
                    @content={{STATUS_OPTIONS}}
                    @onChange={{fn this.onStatusChange field}}
                    @options={{hash
                      clearable=true
                      none="boards.manage.columns.move_to_status_none"
                    }}
                    @value={{data.move_to_status}}
                  />
                </field.Control>
              </form.Field>

              {{#if this.showAdvanced}}
                {{#if this.showMoveToCategoryField}}
                  <form.Field
                    @format="max"
                    @name="move_to_category_id"
                    @title={{i18n "boards.manage.columns.move_to_category"}}
                    @type="custom"
                    as |field|
                  >
                    <field.Control>
                      <CategoryChooser
                        @onChange={{fn this.onCategoryChange field}}
                        @options={{hash clearable=true}}
                        @value={{readonly data.move_to_category_id}}
                      />
                    </field.Control>
                  </form.Field>
                {{/if}}

                <form.Field
                  @format="max"
                  @name="move_to_assigned"
                  @title={{i18n "boards.manage.columns.move_to_assigned"}}
                  @type="custom"
                  as |field|
                >
                  <field.Control>
                    <ComboBox
                      @content={{ASSIGNED_OPTIONS}}
                      @onChange={{fn this.onAssignedModeChange field}}
                      @options={{hash
                        clearable=true
                        none="boards.manage.columns.move_to_assigned_none"
                      }}
                      @value={{assignedMode data.move_to_assigned}}
                    />
                    {{#if (eq (assignedMode data.move_to_assigned) "_user")}}
                      <EmailGroupUserChooser
                        @onChange={{fn this.onAssignedUserChange field}}
                        @options={{hash maximum=1}}
                        @value={{assignedUserValue data.move_to_assigned}}
                      />
                    {{/if}}
                  </field.Control>
                </form.Field>
              {{/if}}
            </form.Section>
          </div>

          <form.Actions>
            <form.Submit class="discourse-boards-column-settings-modal__save" />
            <form.Button
              class="btn-flat d-modal-cancel discourse-boards-column-settings-modal__cancel"
              @action={{@closeModal}}
              @label="cancel"
            />
            <DButton
              class="btn-default show-advanced"
              @action={{this.toggleAdvanced}}
              @icon="gear"
              @title={{if
                this.showAdvanced
                "boards.manage.columns.hide_advanced"
                "boards.manage.columns.show_advanced"
              }}
            />
          </form.Actions>
        </Form>
      </:body>
    </DModal>
  </template>
}
