                  </div>
                {{/if}}

                <div class="discourse-boards-board-card__columns">
                  {{#if board.columns.length}}
                    {{#each board.columns as |column|}}
                      <span class="discourse-boards-column-pill">
                        {{#if column.icon}}
                          {{dIcon column.icon}}
                        {{/if}}
                        {{column.fancyTitle}}
