                    {{/each}}
                  {{else}}
                    <span class="discourse-boards-board-card__no-columns">
                      {{i18n "boards.manage.no_columns"}}
                    </span>
                  {{/if}}
                </div>

                <div class="discourse-boards-board-card__footer">
                  <div
                    class="discourse-boards-board-card__owners discourse-boards-badge"
