import { setOwner } from "@ember/owner";
import { service } from "@ember/service";
import { bind } from "discourse/lib/decorators";
import { withPluginApi } from "discourse/lib/plugin-api";
import BoardsMenu from "../components/boards-menu.gjs";
import {
  boardsTagsHtml,
  membershipsFor,
  MULTI_BOARD_TRIGGER_SELECTOR,
} from "../lib/boards-topic-pill.js";

/**
 * Topic pills are rendered as tags, as raw HTML, so there is no component to
 * hang a click handler on. Boards are delegated from the app root the way
 * discourse-local-dates opens its date popover.
 */
class BoardsTopicPills {
  @service menu;

  // keyed by the trigger, so a menu is built once per pill and goes away with it
  #menus = new WeakMap();

  constructor(owner) {
    setOwner(this, owner);

    withPluginApi((api) => api.addTagsHtmlCallback(boardsTagsHtml));

    this.rootElement = document.querySelector(owner.rootElement);
    this.rootElement?.addEventListener("click", this.onClick);
    this.rootElement?.addEventListener("keydown", this.onKeydown);
  }

  @bind
  onClick(event) {
    return this.#toggleMenu(event);
  }

  @bind
  onKeydown(event) {
    if (event.key === "Enter" || event.key === " ") {
      return this.#toggleMenu(event);
    }
  }

  teardown() {
    this.rootElement?.removeEventListener("click", this.onClick);
    this.rootElement?.removeEventListener("keydown", this.onKeydown);
    this.rootElement = null;
  }

  #toggleMenu(event) {
    const trigger = event.target.closest(MULTI_BOARD_TRIGGER_SELECTOR);
    if (!trigger) {
      return;
    }

    event.preventDefault();

    const instance = this.#menuFor(trigger);
    return instance.expanded ? instance.close() : instance.show();
  }

  #menuFor(trigger) {
    let instance = this.#menus.get(trigger);

    if (!instance) {
      instance = this.menu.newInstance(trigger, {
        identifier: "discourse-boards-topic-pill",
        component: BoardsMenu,
        modalForMobile: true,
        data: { memberships: membershipsFor(trigger) },
        onShow: () => trigger.setAttribute("aria-expanded", "true"),
        onClose: () => trigger.setAttribute("aria-expanded", "false"),
      });
      this.#menus.set(trigger, instance);
    }

    return instance;
  }
}

export default {
  name: "discourse-boards-topic-pill",

  initialize(_container, owner) {
    this.instance = new BoardsTopicPills(owner);
  },

  teardown() {
    this.instance?.teardown();
    this.instance = null;
  },
};
/*
Fabricators are used to create fake data for testing purposes.
The following fabricators are available in lib folder to allow
styleguide to use them, and eventually to generate dummy data
in a placeholder component. It should not be used for any other case.
*/
import ApplicationInstance from "@ember/application/instance";
import { setOwner } from "@ember/owner";
import CoreFabricators, { incrementSequence } from "discourse/lib/fabricators";
import Board from "../models/board.js";
import Card from "../models/card.js";
import Column from "../models/column.js";

export default class BoardsFabricators {
  constructor(owner) {
    if (owner && !(owner instanceof ApplicationInstance)) {
      throw new Error(
        "First argument of BoardsFabricators constructor must be the owning ApplicationInstance"
      );
    }
    setOwner(this, owner);
    this.coreFabricators = new CoreFabricators(owner);
  }

  card(args = {}) {
    return Card.create({
      id: args.id || incrementSequence(),
      title: args.title || "Test Card",
      unicode_title: args.unicode_title,
      card_type: args.card_type || (args.topic ? "topic" : "floater"),
      notes: args.notes || "This is a test card",
      created_at: args.created_at || moment(),
      created_by: args.created_by || this.coreFabricators.user(),
      board_id: args.board_id,
      column_id: args.column_id,
      // TODO: Add assign fabricator with avatar_template, type, and username
      assigned_to: args.assigned_to,
      inline_onebox_data: args.inline_onebox_data,
      tags: args.tags || [],
      tag_ids: args.tag_ids || [],
      topic_id: args.topic?.id || null,
      topic: args.topic || null,
    });
  }

  board(args = {}) {
    return Board.create({
      id: args.id || incrementSequence(),
      name: args.name || "Test Board",
      unicode_name: args.unicode_name,
      slug: args.slug || "test-board",
      columns: args.columns || [],
      can_write: args.can_write ?? true,
      can_manage: args.can_manage ?? true,
      owners: args.owners || [this.coreFabricators.user()],
    });
  }

  column(args = {}) {
    return Column.create({
      id: args.id || incrementSequence(),
      title: args.title || "Test Column",
      unicode_title: args.unicode_title,
      position: args.position || 0,
    });
  }
}
import { service } from "@ember/service";
import { ajax } from "discourse/lib/ajax";
