import { ajax } from "discourse/lib/ajax";
import DiscourseRoute from "discourse/routes/discourse";
import Board from "../models/board.js";

export default class BoardsBoardConfigureRoute extends DiscourseRoute {
  @service router;

  titleToken() {
    return this.controller?.model?.board?.fancyTitle;
  }

  model(params) {
    return ajax(`/boards/api/boards/${params.id}.json`).then((data) =>
      Board.createPayload({ ...data, openBoardSettings: true })
    );
  }

  afterModel(model, transition) {
    const board = model.board;

    if (board && !board.canManage) {
      this.router.replaceWith("boardsBoard", board.slug, board.id);
      return;
    }

    if (board?.slug && transition.to.params.slug !== board.slug) {
      this.router.replaceWith("boardsBoardConfigure", board.slug, board.id);
    }
  }
}
import { service } from "@ember/service";
import { ajax } from "discourse/lib/ajax";
import DiscourseRoute from "discourse/routes/discourse";
import { sortCardsForColumn } from "../lib/boards-card-ordering.js";
import Board from "../models/board.js";

export default class BoardsBoardRoute extends DiscourseRoute {
  @service router;

  queryParams = {
    card: { refreshModel: true },
  };

  titleToken() {
    return this.controller?.model?.board?.fancyTitle;
  }

  model(params, transition) {
    return ajax(`/boards/api/boards/${params.id}.json`).then((data) =>
      Board.createPayload({
        ...data,
        highlightCardId: parseInt(transition.to.queryParams.card, 10) || null,
      })
    );
  }

  afterModel(model, transition) {
    const board = model.board;
    if (board?.slug && transition.to.params.slug !== board.slug) {
      this.router.replaceWith("boardsBoard", board.slug, board.id, {
        queryParams: { card: transition.to.queryParams.card },
      });
    }

    model.board.columns = model.board.columns.map((col) => {
      col.cards = sortCardsForColumn(col, col.cards || []);
      return col;
    });
  }
}
import { ajax } from "discourse/lib/ajax";
import DiscourseRoute from "discourse/routes/discourse";
import { i18n } from "discourse-i18n";
import { preloadCategories } from "../lib/boards-categories.js";
import Board from "../models/board.js";

export default class BoardsRoute extends DiscourseRoute {
  titleToken() {
    return i18n("boards.manage.title");
  }

  async model() {
    const data = await ajax("/boards/api/boards.json");
    await preloadCategories(
      data.boards.flatMap((board) => board.category_ids || [])
    );

    return data.boards.map((board) => Board.create(board));
  }
}
